  ('ef16d072-8b9b-49e2-8fda-0d6dc7997382', private.editorial_id(), 'water_body', 'Азербай', 'Озеро площадью около 2,1 км² в Костанайской области. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(65.546812 49.785492)', null, '{"source": "osm", "osm": "w626120810", "features": "Площадь около 2,1 км² (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('1f594faa-a439-4ad9-ba4e-9f13cb0ccc6b', private.editorial_id(), 'water_body', 'Айбас', 'Озеро площадью около 2 км² в 29 км к юго-западу от г. Курчатов, в Павлодарской области.', 'SRID=4326;POINT(78.303519 50.552475)', null, '{"source": "osm", "osm": "r17435785", "features": "Площадь около 2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('32620c06-86f3-43d1-bd20-f48d508b894e', private.editorial_id(), 'water_body', 'Айдын', 'Озеро площадью около 7,7 км² в 2 км к северу от с. Жанаказан, в Западно-Казахстанской области.', 'SRID=4326;POINT(49.611960 48.951484)', null, '{"source": "osm", "osm": "w39493220", "features": "Площадь около 7,7 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('34a36d26-c067-4eba-95f0-7c5032b824c6', private.editorial_id(), 'water_body', 'Айколь', 'Высокогорное озеро в Заилийском Алатау на высоте около 3400 м, в 50 км к юго-западу от центра Алматы по прямой. На такой высоте озеро свободно ото льда только летом, а погода в горах меняется быстро: идите с прогнозом и скажите близким маршрут.', 'SRID=4326;POINT(76.508398 42.925919)', null, '{"source": "osm", "osm": "w1064829733", "features": "Высота около 3400 м."}', 'public', false, 'published'),
  ('34317bda-a6d4-4411-8aec-1f39508543e6', private.editorial_id(), 'water_body', 'Айнабулак-3', 'Озеро площадью около 97 га в 2 км к северо-западу от с. Космос, в Алматинской области.', 'SRID=4326;POINT(77.242803 43.516040)', null, '{"source": "osm", "osm": "w23651698", "features": "Площадь около 97 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('a22d6ad7-5456-4a4c-ae60-e22e17715e81', private.editorial_id(), 'water_body', 'Айнаколь', 'Озеро площадью около 44 га у с. Айнаколь, в Акмолинской области.', 'SRID=4326;POINT(69.688300 51.858344)', null, '{"source": "osm", "osm": "w150169937", "features": "Площадь около 44 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('31d0d0b7-752e-490e-9a14-5023349cec71', private.editorial_id(), 'water_body', 'Айткожаколь', 'Озеро площадью около 78 га в 3 км к западу от с. Жанакуш, в Западно-Казахстанской области. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(54.146569 50.969900)', null, '{"source": "osm", "osm": "w1279886674", "features": "Площадь около 78 га (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('fb9069a2-8fd9-443c-a83d-298724113ec9', private.editorial_id(), 'water_body', 'Айтысколь (сол.)', 'Озеро площадью около 17 га в 11 км к западу от с. Акжал, в Карагандинской области.', 'SRID=4326;POINT(75.436289 49.696814)', null, '{"source": "osm", "osm": "w428432211", "features": "Площадь около 17 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('3c07b7ec-f53e-4e39-96f2-2ddfb443b6a5', private.editorial_id(), 'water_body', 'Айырколь', 'Озеро площадью около 18 км² в 6 км к северу от с. Нура, в Актюбинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(62.292510 48.947422)', null, '{"source": "osm", "osm": "w397798271", "features": "Площадь около 18 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('082e4203-f30a-49ad-92ca-7a3650294f58', private.editorial_id(), 'water_body', 'Акай', 'Старица площадью около 21 га в 7 км к северо-западу от с. Дуана, в Западно-Казахстанской области. По данным OpenStreetMap, вода солёная, а озеро временами пересыхает. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(51.461977 50.334170)', null, '{"source": "osm", "osm": "r7226796", "features": "Площадь около 21 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('08c74bc4-15ee-4cab-a3b1-b263efb59034', private.editorial_id(), 'water_body', 'Акбас', 'Озеро площадью около 4,4 км² в 4 км к северо-западу от с. Сырымбет, в Северо-Казахстанской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(67.952958 53.507614)', null, '{"source": "osm", "osm": "w536329748", "features": "Площадь около 4,4 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('0f8214a1-581c-433c-ab87-4d7a12f25846', private.editorial_id(), 'water_body', 'Акбастыколь', 'Озеро площадью около 1,9 км² у с. Жанажол, в Северо-Казахстанской области.', 'SRID=4326;POINT(66.470728 54.394014)', null, '{"source": "osm", "osm": "w536824773", "features": "Площадь около 1,9 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('6730b803-62fb-4aa0-b10a-0bda28fae3e6', private.editorial_id(), 'water_body', 'Акбота', 'Озеро площадью около 4,5 км² в Павлодарской области.', 'SRID=4326;POINT(78.554119 50.269539)', null, '{"source": "osm", "osm": "r12604011", "features": "Площадь около 4,5 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('f785fbba-06c3-40e5-865a-06b310471321', private.editorial_id(), 'water_body', 'Акжол', 'Озеро площадью около 2 км² в 16 км к северо-востоку от с. Раздольное, в Костанайской области. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(63.338865 51.571738)', null, '{"source": "osm", "osm": "r5606700", "features": "Площадь около 2 км² (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('d05c05df-ed3f-4d74-befa-3c8ff2a92ac8', private.editorial_id(), 'water_body', 'Аккол', 'Озеро площадью около 1,1 км² в 11 км к юго-востоку от с. Тасоткель, в Кызылординской области.', 'SRID=4326;POINT(62.075047 45.339890)', null, '{"source": "osm", "osm": "w698505860", "features": "Площадь около 1,1 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('eabc5001-74a5-47a3-8776-018a0f0105ab', private.editorial_id(), 'water_body', 'Аккол-Ердес', 'Озеро площадью около 86 га в 13 км к юго-востоку от с. Тасоткель, в Кызылординской области.', 'SRID=4326;POINT(62.092824 45.327751)', null, '{"source": "osm", "osm": "w698505859", "features": "Площадь около 86 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('0a732936-423e-42f3-bd43-4aaaf5a611c9', private.editorial_id(), 'water_body', 'Акколь (с. Акколь, Жамбылская обл.)', 'Озеро в 3 км к юго-западу от с. Акколь — центра Таласского района. Площадь — около 36 км²; наибольшая глубина — 5 м. Через озеро течёт река Асса. Водятся сазан, алабуга (окунь) и другие рыбы. Замерзает с конца декабря по конец марта; берег — место отдыха.', 'SRID=4326;POINT(70.687529 43.409080)', null, '{"source": "osm", "osm": "w38860887", "species": ["common_carp", "perch"], "features": "Площадь 36 км², наибольшая глубина 5 м (средняя 3 м), высота над уровнем моря 397 м. Впадает: Асса. Вытекает: Асса."}', 'public', false, 'published'),
  ('b78a1939-6eba-4572-bea4-e432e850da34', private.editorial_id(), 'water_body', 'Акколь', 'Высокогорное озеро в Заилийском Алатау на высоте около 3100 м, в 46 км к востоку от центра Алматы по прямой. На такой высоте озеро свободно ото льда только летом, а погода в горах меняется быстро: идите с прогнозом и скажите близким маршрут.', 'SRID=4326;POINT(77.485838 43.126726)', null, '{"source": "osm", "osm": "w230078064", "features": "Высота около 3100 м."}', 'public', false, 'published'),
  ('4db3f9aa-9252-4d87-9fcd-846b5445a210', private.editorial_id(), 'water_body', 'Акколь (Карагандинская обл.)', 'Озеро площадью около 95 га в 22 км к северу от с. Беталыс, в Карагандинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(75.283844 49.778606)', null, '{"source": "osm", "osm": "w428432187", "features": "Площадь около 95 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('47889226-455f-4ae7-95f1-b9fa13099142', private.editorial_id(), 'water_body', 'Акколь (Костанайская обл.)', 'Озеро площадью около 59 км² в 13 км к западу от с. Село Ахмета Байтурсынулы, в Костанайской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(63.731619 48.825332)', null, '{"source": "osm", "osm": "w220149742", "features": "Площадь около 59 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('9b3ebb8f-16bc-4fe8-85d4-33ab7d3e76fd', private.editorial_id(), 'water_body', 'Аксайские озера', 'Высокогорные озёра в Заилийском Алатау на высоте около 3350 м, в 32 км к юго-западу от центра Алматы по прямой. На такой высоте озёра свободны ото льда только летом, а погода в горах меняется быстро: идите с прогнозом и скажите близким маршрут.', 'SRID=4326;POINT(76.746067 42.993331)', null, '{"source": "osm", "osm": "r17035153", "features": "Высота около 3350 м."}', 'public', false, 'published'),
  ('4e2f442a-199b-4fdf-b794-bc6a00ab1464', private.editorial_id(), 'water_body', 'Аксу', 'Озеро площадью около 81 га в 4 км к юго-востоку от с. Аксу, в Жамбылской области.', 'SRID=4326;POINT(74.060283 43.225941)', null, '{"source": "osm", "osm": "w189791824", "features": "Площадь около 81 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('d15d3214-f09a-40c2-abb8-6d0b48a0b0f8', private.editorial_id(), 'water_body', 'Аксуат (с. Москворецкое, СКО)', 'Озеро площадью около 15 км² в 6 км к востоку от с. Москворецкое, в Северо-Казахстанской области.', 'SRID=4326;POINT(66.446715 53.676067)', null, '{"source": "osm", "osm": "w42179024", "features": "Площадь около 15 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('87d62f11-9d7e-44e0-9eeb-abad4c39af6c', private.editorial_id(), 'water_body', 'Аксуат (с. Рублёвка, СКО)', 'Озеро площадью около 3,7 км² в 2 км к западу от с. Рублёвка, в Северо-Казахстанской области. По данным OpenStreetMap, вода солёная, а озеро временами пересыхает. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(69.112125 54.276899)', null, '{"source": "osm", "osm": "w209082221", "features": "Площадь около 3,7 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('96bf6399-5224-40a3-98e9-09a530c45c6c', private.editorial_id(), 'water_body', 'Актастыкуль', 'Озеро площадью около 2,9 км² в 20 км к юго-востоку от с. Караганда, в Актюбинской области.', 'SRID=4326;POINT(59.847252 50.546545)', null, '{"source": "osm", "osm": "w206097717", "features": "Площадь около 2,9 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('4a349526-f395-46db-b040-89b9a02838cc', private.editorial_id(), 'water_body', 'Актинод', 'Озеро площадью около 6 га в 2 км к югу от с. Музбель, в Жамбылской области, на высоте около 1050 м.', 'SRID=4326;POINT(74.930054 43.291569)', null, '{"source": "osm", "osm": "w1230086192", "features": "Площадь около 6 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('0a93d5a4-c890-4c0b-8d1b-535b7ce12f58', private.editorial_id(), 'water_body', 'Актюбинское водохранилище', '«Актюбинское море» — водохранилище на реке Илек в 10 км к юго-востоку от Актобе, введено в 1988 году. Водятся сазан, лещ, окунь, язь, судак, рипус, плотва и карась; в 2012 году сюда выпустили 2 млн мальков рипуса.', 'SRID=4326;POINT(57.318024 50.196341)', null, '{"source": "osm", "osm": "r11949187", "species": ["common_carp", "bream", "perch", "ide", "zander", "vendace", "roach", "crucian_carp"], "features": "Объём 245 млн м³."}', 'public', false, 'published'),
  ('2b18c6d2-e2fe-4bf1-b3c0-81c00229b555', private.editorial_id(), 'water_body', 'Акшкольское', 'Озеро площадью около 3 км² в 7 км к северу от с. Боке, в области Абай. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(81.581375 49.154613)', null, '{"source": "osm", "osm": "w552151980", "features": "Площадь около 3 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('75332a8b-32e0-4742-a7c0-a1ecd1d23412', private.editorial_id(), 'water_body', 'Алаайгырское водохранилище.', 'Водохранилище площадью около 5 га у с. Солнечное, в области Абай.', 'SRID=4326;POINT(81.614294 49.688400)', null, '{"source": "osm", "osm": "w670160627", "features": "Площадь около 5 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('23694a6d-9632-4c73-9586-ed284fe900f7', private.editorial_id(), 'water_body', 'Алабайское водохранилище', 'Водохранилище площадью около 1,6 км² в черте Шымкента.', 'SRID=4326;POINT(69.506017 42.409866)', null, '{"source": "osm", "osm": "w1458773050", "features": "Площадь около 1,6 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('a598e88e-a2b4-495f-9c6c-980d38e538b2', private.editorial_id(), 'water_body', 'Алабота', 'Бывшее пресное озеро, теперь — болото, в 8 км к востоку от с. Жанчилик, в Костанайской области. Площадь — около 37 км². Открытой воды может не быть.', 'SRID=4326;POINT(65.419164 52.747955)', null, '{"source": "osm", "osm": "w1271929624", "features": "Площадь 37 км², длина 9,6 км, ширина 5 км, высота над уровнем моря 199 м."}', 'public', false, 'published'),
  ('40db63d1-4f49-4c5f-a994-d08fd3b1d93f', private.editorial_id(), 'water_body', 'Алаколь', 'Горько-солёное бессточное озеро на границе Абайской и Жетысуской областей; на западном берегу — курортные посёлки Акши и Коктума, от Алматы — 9–10 часов на машине. Ведётся промысел маринки, губача, окуня, судака, леща и сазана. Ледостав — с января по апрель.', 'SRID=4326;POINT(81.747559 46.000346)', null, '{"source": "osm", "osm": "r35889", "species": ["marinka", "perch", "zander", "bream", "common_carp"], "methods": ["shore", "boat", "ice"], "features": "Площадь около 2700 км², глубина до 54 м (в среднем 22 м), солёность около 8 г/л."}', 'public', false, 'published'),
  ('ffc7f449-4f83-4391-8396-3af0a448ff0a', private.editorial_id(), 'water_body', 'Алаколь (с. Аксуат, Костанайская обл.)', 'Пресное озеро у с. Аксуат, в Мендыкаринском районе. Площадь — около 18 км². В озеро впадает река Кайранкалык; рядом проходит трасса А-21.', 'SRID=4326;POINT(64.703508 53.890224)', null, '{"source": "osm", "osm": "w151568744", "features": "Площадь 17,5 км², длина 7,5 км, ширина 3 км, высота над уровнем моря 94 м. Впадает: Кайранкалык. Вода пресная."}', 'public', false, 'published'),
  ('aa07a028-d2cc-4723-9721-fd28319a82cd', private.editorial_id(), 'water_body', 'Алаколь (Акмолинская обл.)', 'Озеро площадью около 47 км² в 9 км к северо-западу от с. Коркем, в Акмолинской области.', 'SRID=4326;POINT(69.694445 51.218452)', null, '{"source": "osm", "osm": "w313289138", "features": "Площадь около 47 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('78bb202f-8c73-41d8-ae69-93874ece3b59', private.editorial_id(), 'water_body', 'Алаколь (СКО)', 'Озеро площадью около 3,5 км² в 8 км к северо-востоку от с. Ольговка, в Северо-Казахстанской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(66.685674 54.424921)', null, '{"source": "osm", "osm": "w536824766", "features": "Площадь около 3,5 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('317cd9d4-90be-4dc7-88b7-2519ee0ee7cc', private.editorial_id(), 'water_body', 'Алебастарский водохранилище', 'Водохранилище площадью около 1,1 км² в 2 км к югу от с. Алебастр, в Восточно-Казахстанской области.', 'SRID=4326;POINT(82.339723 49.866409)', null, '{"source": "osm", "osm": "w41818375", "features": "Площадь около 1,1 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('9ad417ca-8960-463e-aadf-12e6ed42a7bf', private.editorial_id(), 'water_body', 'Алкаколь', 'Озеро площадью около 28 га в 7 км к юго-западу от с. Жанаонир, в Западно-Казахстанской области.', 'SRID=4326;POINT(52.026129 50.508224)', null, '{"source": "osm", "osm": "r7192809", "features": "Площадь около 28 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('6cdbd884-8403-4253-bf8e-95ef38ced3dc', private.editorial_id(), 'water_body', 'Алкамерген', 'Озеро площадью около 44 км² в Павлодарской области. По данным OpenStreetMap, вода солёная, а озеро временами пересыхает. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(76.651676 51.135274)', null, '{"source": "osm", "osm": "w403309103", "features": "Площадь около 44 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('db5afc1e-ef24-4b13-b6b0-c0de93a82d6b', private.editorial_id(), 'water_body', 'Алма-Атинское водохранилище', 'Водохранилище в Алматинской области, в 28 км к северу от центра Алматы по прямой, на высоте около 610 м. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(76.949592 43.487846)', null, '{"source": "osm", "osm": "r19120298"}', 'public', false, 'published'),
  ('d50f64ca-3365-4336-a53e-d3097ddf46a8', private.editorial_id(), 'water_body', 'Алмалы', 'Озеро площадью около 42 га в 14 км к западу от с. Коктобе, в области Жетісу.', 'SRID=4326;POINT(78.539823 45.135787)', null, '{"source": "osm", "osm": "w683887872", "features": "Площадь около 42 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('693f6d67-af01-419b-9ba4-27145faf77bd', private.editorial_id(), 'water_body', 'Алтын Куль', 'Озеро площадью около 6 га в 4 км к югу от с. Ынтымак, в области Жетісу.', 'SRID=4326;POINT(80.210975 44.153743)', null, '{"source": "osm", "osm": "w268940425", "features": "Площадь около 6 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('4e209397-49c5-4bfc-bea9-d191f9ca2654', private.editorial_id(), 'water_body', 'Альпаш озеро', 'Озеро площадью около 17 км² в 3 км к северо-востоку от с. Комсомольское, в Северо-Казахстанской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(66.442603 53.773807)', null, '{"source": "osm", "osm": "w539977648", "features": "Площадь около 17 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('88ba01d0-281b-4732-96bc-c4e6eb3e1052', private.editorial_id(), 'water_body', 'Амангельдинское водохранилище', 'Небольшое водохранилище на Тоболе в Костанайском районе Костанайской области, образовано в 1964 году; вместе с Верхнетобольским и Каратомарским входит в каскад на Тоболе.', 'SRID=4326;POINT(63.587238 53.124225)', null, '{"source": "osm", "osm": "r9202149", "features": "Площадь 4,16 км², проектный объём 6,75 млн м³."}', 'public', false, 'published'),
  ('300d4a35-51ff-4302-bc3e-d5a3a17fc744', private.editorial_id(), 'water_body', 'Анисимово озеро', 'Озеро площадью около 12 га у г. Зачаганск, в Западно-Казахстанской области.', 'SRID=4326;POINT(51.328087 51.179118)', null, '{"source": "osm", "osm": "w283352937", "features": "Площадь около 12 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('c7f67fde-73af-4147-926f-dcb153d570e6', private.editorial_id(), 'water_body', 'Апсикей', 'Озеро площадью около 1,3 км² в 7 км к востоку от с. Борисовка, в Акмолинской области.', 'SRID=4326;POINT(68.640205 51.895552)', null, '{"source": "osm", "osm": "w325440889", "features": "Площадь около 1,3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('9ed7b17f-b321-4e2b-b323-5e41f4e7dbeb', private.editorial_id(), 'water_body', 'Озеро на острове', 'Озеро площадью около 40 га в 8 км к северу от с. Жулдыз, в Туркестанской области.', 'SRID=4326;POINT(68.530913 41.020957)', null, '{"source": "osm", "osm": "r18345594", "features": "Площадь около 40 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('7507233e-f6ab-4c02-b10f-5b9d29186a4f', private.editorial_id(), 'water_body', 'Аралтобе (с. Жанатай, Костанайская обл.)', 'Озеро площадью около 3,6 км² в 30 км к юго-востоку от с. Жанатай, в Костанайской области. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(65.383161 49.810295)', null, '{"source": "osm", "osm": "w626120815", "features": "Площадь около 3,6 км² (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('40f1733d-5296-44fb-bd6a-c491db2a89c5', private.editorial_id(), 'water_body', 'Арасан', 'Горное озеро на высоте около 1750 м у села Рахмановские Ключи в Катон-Карагайском районе Восточно-Казахстанской области.', 'SRID=4326;POINT(86.481899 49.537499)', null, '{"source": "osm", "osm": "r11522982", "features": "Высота около 1750 м."}', 'public', false, 'published'),
  ('2aaece9d-c385-4588-9e2d-68f8a44052b2', private.editorial_id(), 'water_body', 'Арыкбалык', 'Озеро площадью около 2,2 км² у с. Арыкбалык, в Северо-Казахстанской области.', 'SRID=4326;POINT(68.213295 52.946532)', null, '{"source": "osm", "osm": "w24949429", "features": "Площадь около 2,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('4e526604-43bc-459c-bc1c-590713e21c10', private.editorial_id(), 'water_body', 'Асубалык', 'Озеро площадью около 13 км² в 17 км к северо-западу от с. Ныгман, в Акмолинской области.', 'SRID=4326;POINT(69.243168 50.418601)', null, '{"source": "osm", "osm": "w277032681", "features": "Площадь около 13 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('467ae097-68c2-4bf1-8a4b-32121de01c81', private.editorial_id(), 'water_body', 'Атаманское озеро', 'Озеро площадью около 1,1 км² в 6 км к западу от с. Макарьевка, в Северо-Казахстанской области.', 'SRID=4326;POINT(66.256274 54.501981)', null, '{"source": "osm", "osm": "w251775602", "features": "Площадь около 1,1 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('72ac51e6-70fc-4443-8b57-366136629af7', private.editorial_id(), 'water_body', 'Аупельдек', 'Озеро площадью около 1 га в 4 км к северу от с. Джыланды, в области Абай.', 'SRID=4326;POINT(79.860793 50.682144)', null, '{"source": "osm", "osm": "w256058180", "features": "Площадь около 1 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('5983d167-b975-4113-a703-2199c7fbbedd', private.editorial_id(), 'water_body', 'Ащисуйское водохранилище', 'Водохранилище многолетнего регулирования на реке Ащысу в Бухар-Жырауском районе Карагандинской области; объём — около 20 млн м³. Название — от реки Ащысу («горькая вода»): это водохранилище на реке, а не солёное озеро.', 'SRID=4326;POINT(74.337594 49.957327)', null, '{"source": "osm", "osm": "r34268", "features": "Объём около 20 млн м³."}', 'public', false, 'published'),
  ('1733dc9b-cb57-466e-9ac8-44f6bf269188', private.editorial_id(), 'water_body', 'Аякколь озеро', 'Озеро площадью около 99 га у с. Ульго, в Северо-Казахстанской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(69.981727 54.541988)', null, '{"source": "osm", "osm": "w200020373", "features": "Площадь около 99 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('74dc3265-4575-44fc-aecc-0aee92527c06', private.editorial_id(), 'water_body', 'Ақжайқын', 'Солёное бессточное озеро (или группа озёр) во впадине Ащыколь, в 100 км от аула Созак. Площадь — около 48 км²; наибольшая глубина — 3 м. Река Шу доходит до озера только в половодье, площадь и глубина меняются с осадками. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(67.781024 44.908517)', null, '{"source": "osm", "osm": "w75990503", "features": "Площадь 48,2 км², наибольшая глубина 3 м, высота над уровнем моря около 130 м. Впадает: Чу. Вода солёная."}', 'public', false, 'published'),
  ('aafe7f90-d0a8-49da-a816-ee73f240adf1', private.editorial_id(), 'water_body', 'Ақкөл', 'Озеро площадью около 3 км² у г. Акколь, в Акмолинской области.', 'SRID=4326;POINT(70.958675 52.007561)', null, '{"source": "osm", "osm": "w250287191", "features": "Площадь около 3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('fafa208b-c8f7-45ee-9f5e-766ee226b76f', private.editorial_id(), 'water_body', 'Бабаши', 'Озеро площадью около 8 га у с. Вишневка, в Северо-Казахстанской области.', 'SRID=4326;POINT(69.078679 54.926734)', null, '{"source": "osm", "osm": "w542000338", "features": "Площадь около 8 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('3646193b-bac2-4068-9a84-88b30400d9b8', private.editorial_id(), 'water_body', 'Бабье озеро', 'Озеро площадью около 6 км² у с. Амречье, в Костанайской области.', 'SRID=4326;POINT(65.732937 54.126052)', null, '{"source": "osm", "osm": "r8781399", "features": "Площадь около 6 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('63d39f12-f490-496f-bd87-8208d5a2d5dc', private.editorial_id(), 'water_body', 'Бадамское водохранилище', 'Водохранилище площадью около 3,9 км² в черте Шымкента.', 'SRID=4326;POINT(69.771189 42.221542)', null, '{"source": "osm", "osm": "w113345395", "features": "Площадь около 3,9 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('8da16c2a-db7c-42dd-aefd-d9dda83291a1', private.editorial_id(), 'water_body', 'Байменское водохранилище', 'Водохранилище площадью около 2 км² в 8 км к северо-востоку от с. Баймен, в Акмолинской области.', 'SRID=4326;POINT(73.096275 51.299214)', null, '{"source": "osm", "osm": "w124680304", "features": "Площадь около 2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('68c6ba9d-48fb-4703-a3c0-9e38f064eca9', private.editorial_id(), 'water_body', 'Байтакколь', 'Озеро площадью около 43 км² в 3 км к востоку от с. Байтак, в Актюбинской области.', 'SRID=4326;POINT(62.136117 48.683392)', null, '{"source": "osm", "osm": "w206623251", "features": "Площадь около 43 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('97662c10-9c2f-4a04-9058-ee0fb217f72d', private.editorial_id(), 'water_body', 'Байтарколь', 'Озеро площадью около 1,8 км² в 7 км к северо-западу от с. Беталыс, в Карагандинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(75.215473 49.603068)', null, '{"source": "osm", "osm": "r19999146", "features": "Площадь около 1,8 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('7b55c45c-86b2-485f-be26-46bca71b4e39', private.editorial_id(), 'water_body', 'Бакрай', 'Озеро площадью около 44 га в Акмолинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(73.606093 52.126448)', null, '{"source": "osm", "osm": "w321246386", "features": "Площадь около 44 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('34727383-fa9e-45a2-b1e3-60676a68275f', private.editorial_id(), 'water_body', 'Балхаш', 'Одно из крупнейших озёр Казахстана. Исконные рыбы — маринка и балхашский окунь; вселены сазан, лещ, судак, сом, карась, линь и другие. Лёд стоит с ноября до начала апреля. Летом волны поднимаются до 2–3,5 м — на лодке выходите только в тихую погоду.', 'SRID=4326;POINT(74.666411 46.470596)', null, '{"source": "osm", "osm": "r19025268", "species": ["marinka", "balkhash_perch", "common_carp", "bream", "zander", "wels_catfish", "crucian_carp", "tench"], "methods": ["shore", "boat", "ice"], "features": "Западная часть озера пресная, восточная — солоноватая."}', 'public', false, 'published'),
  ('edbd2125-4542-4f6a-82b8-f5688a7161da', private.editorial_id(), 'water_body', 'Балыктинское озеро', 'Озеро площадью около 82 га в 4 км к юго-востоку от с. Балыкты, в Костанайской области.', 'SRID=4326;POINT(63.162714 52.920799)', null, '{"source": "osm", "osm": "w22498625", "features": "Площадь около 82 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('164ec439-5843-4c14-9465-558e50d9658f', private.editorial_id(), 'water_body', 'Балыкты (Акмолинская обл.)', 'Озеро площадью около 2,6 км² в 6 км к югу от с. Табигат, в Акмолинской области.', 'SRID=4326;POINT(70.760602 51.810918)', null, '{"source": "osm", "osm": "w150289425", "features": "Площадь около 2,6 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('63209a93-62ad-45df-8791-595567eb6a1f', private.editorial_id(), 'water_body', 'Балыкты (Костанайская обл.)', 'Озеро у с. Узунколь, в Костанайской области. Площадь — около 4,5 км²; наибольшая глубина — 2,6 м.', 'SRID=4326;POINT(65.359756 54.028733)', null, '{"source": "osm", "osm": "w153203498", "features": "Площадь 4,52 км², длина 3,1 км, ширина 1,7 км, наибольшая глубина 2,6 м, высота над уровнем моря 168,9 м."}', 'public', false, 'published'),
  ('6b4a0ef9-3728-4383-9797-6e06ea77c28c', private.editorial_id(), 'water_body', 'Балыкты озеро', 'Озеро в 4 км к северу от с. Димитровка, в Северо-Казахстанской области. Площадь — около 17 км². Входит в перечень рыбохозяйственных водоёмов местного значения.', 'SRID=4326;POINT(68.895352 54.268770)', null, '{"source": "osm", "osm": "w231923883", "features": "Площадь 16,58 км², длина 5,2 км, ширина 4,7 км, высота над уровнем моря 129,6 м."}', 'public', false, 'published'),
  ('dc651a04-a767-4d4e-ac5a-eb5635e09921', private.editorial_id(), 'water_body', 'Балыктыколь (Акмолинская обл.)', 'Озеро в 3 км к юго-востоку от с. Камышенка, в Акмолинской области. Площадь — около 25 км²; средняя глубина — 3,0 м.', 'SRID=4326;POINT(70.166266 51.709840)', null, '{"source": "osm", "osm": "w150289426", "features": "Площадь 25,4 км², длина 7,9 км, ширина 4,9 км, средняя глубина 3,0 м, высота над уровнем моря 301 м. Впадает: Шейка."}', 'public', false, 'published'),
  ('5ab8b02f-b24c-49ed-be3e-226068dff120', private.editorial_id(), 'water_body', 'Балыктыколь (Карагандинская обл.)', 'Озеро площадью около 29 км² в 15 км к западу от с. Атантай, в Карагандинской области.', 'SRID=4326;POINT(75.938707 49.795788)', null, '{"source": "osm", "osm": "w27445061", "features": "Площадь около 29 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('46275861-9260-4702-95a2-be95f444eb8f', private.editorial_id(), 'water_body', 'Балыктыколь (Костанайская обл.)', 'Озеро площадью около 3 км² в 3 км к северо-западу от с. Речное, в Костанайской области.', 'SRID=4326;POINT(64.515148 52.460114)', null, '{"source": "osm", "osm": "w27670329", "features": "Площадь около 3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('46a87959-feca-4bf3-bec4-26fa060ab848', private.editorial_id(), 'water_body', 'Балыктыколь (обл. Абай)', 'Озеро площадью около 10 км² в 17 км к северо-западу от с. Кызылтан, в области Абай.', 'SRID=4326;POINT(79.184773 50.364597)', null, '{"source": "osm", "osm": "w39517601", "features": "Площадь около 10 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('d6118bd4-47c6-4cb9-a70d-93f0020c2436', private.editorial_id(), 'water_body', 'Барал-Сы', 'Озеро площадью около 160 км² в 29 км к юго-западу от с. Акбасты, в Кызылординской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(59.938692 46.033995)', null, '{"source": "osm", "osm": "r3334885", "features": "Площадь около 160 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('d098d509-fb19-4326-aeeb-3005633333db', private.editorial_id(), 'water_body', 'Барап', 'Озеро площадью около 7,4 км² в 3 км к западу от с. Малый Барап, в Акмолинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(70.963893 52.092278)', null, '{"source": "osm", "osm": "w304391677", "features": "Площадь около 7,4 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('22ca1908-32e0-4f86-b657-83463302b5a5', private.editorial_id(), 'water_body', 'Баратай', 'Озеро площадью около 2,3 км² в 2 км к северу от с. Баратай, в Акмолинской области.', 'SRID=4326;POINT(68.588589 53.432036)', null, '{"source": "osm", "osm": "w353042343", "features": "Площадь около 2,3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b8ac7b9d-bf76-42f5-8f47-c1d0d789d27e', private.editorial_id(), 'water_body', 'Барлыколь', 'Озеро площадью около 1,3 км² в 12 км к северо-востоку от с. Острогорское, в Акмолинской области.', 'SRID=4326;POINT(69.762137 52.002299)', null, '{"source": "osm", "osm": "w150169939", "features": "Площадь около 1,3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('bc99b10b-54ba-48bf-8623-9e53e7fe8fc5', private.editorial_id(), 'water_body', 'Бартогайское водохранилище', 'Водохранилище на реке Чилик в Енбекшиказахском районе Алматинской области, в 10 км от аула Асы-Сага; сдано в 1986 году и орошает земли у подножия Иле Алатау. Длина — 6 км, ширина — 3 км, средняя глубина — 25 м. Водятся сазан и карп, карась, форель.', 'SRID=4326;POINT(78.505530 43.353722)', null, '{"source": "osm", "osm": "r19802418", "species": ["common_carp", "crucian_carp", "rainbow_trout"], "features": "Длина 6 км, ширина 3 км, средняя глубина 25 м, площадь 13 км², объём 320 млн м³."}', 'public', false, 'published'),
  ('b877f6c1-2f68-467d-9ac7-e9e75902948b', private.editorial_id(), 'water_body', 'Бартугуль', 'Высокогорное озеро в Заилийском Алатау на высоте около 3200 м, в 68 км к востоку от центра Алматы по прямой. На такой высоте озеро свободно ото льда только летом, а погода в горах меняется быстро: идите с прогнозом и скажите близким маршрут.', 'SRID=4326;POINT(77.771233 43.129962)', null, '{"source": "osm", "osm": "w1232458078", "features": "Высота около 3200 м."}', 'public', false, 'published'),
  ('eba34e40-7cd4-4f21-9a86-3f1e1cf364a0', private.editorial_id(), 'water_body', 'Батантай', 'Озеро площадью около 92 га у с. Гуляйполе, в Акмолинской области.', 'SRID=4326;POINT(70.649522 51.793118)', null, '{"source": "osm", "osm": "w150289420", "features": "Площадь около 92 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('f929b1d0-4d91-436d-ac5f-e002a914cec8', private.editorial_id(), 'water_body', 'Батпаколь', 'Озеро площадью около 32 км² в Актюбинской области.', 'SRID=4326;POINT(57.825073 48.278686)', null, '{"source": "osm", "osm": "w1503261172", "features": "Площадь около 32 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('1479c202-579e-4868-93af-1e704643c97f', private.editorial_id(), 'water_body', 'Батырша', 'Озеро площадью около 7,2 км² в Павлодарской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(76.394278 51.536766)', null, '{"source": "osm", "osm": "w403244529", "features": "Площадь около 7,2 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('f271b1c6-5515-41a0-b063-27b04a1cf623', private.editorial_id(), 'water_body', 'Башенное озеро', 'Озеро площадью около 99 га в 6 км к северо-западу от с. Калиновка, в Северо-Казахстанской области.', 'SRID=4326;POINT(66.377763 54.614169)', null, '{"source": "osm", "osm": "w1221006177", "features": "Площадь около 99 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('1c6ce012-a3c0-4a64-b67c-c929aaee8649', private.editorial_id(), 'water_body', 'Башкирское (с. Подувальная, СКО)', 'Озеро в 4 км к югу от с. Подувальная, в Северо-Казахстанской области. Площадь — около 1,3 км². Входит в перечень рыбохозяйственных водоёмов местного значения.', 'SRID=4326;POINT(67.511655 54.830271)', null, '{"source": "osm", "osm": "w536844286", "features": "Площадь 1,28 км², длина 1,4 км, ширина 1,1 км, высота над уровнем моря 138,3 м."}', 'public', false, 'published'),
  ('d20d0eaf-23cc-47a9-8ac1-b8b6c6929c8f', private.editorial_id(), 'water_body', 'Башкирское озеро', 'Озеро площадью около 73 га в 3 км к северо-западу от с. Пресное, в Павлодарской области.', 'SRID=4326;POINT(76.502044 52.876919)', null, '{"source": "osm", "osm": "w124309615", "features": "Площадь около 73 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('eba7fa8e-b108-4d90-92b0-fa75f24e1c48', private.editorial_id(), 'water_body', 'Баямбай', 'Озеро площадью около 94 га в 5 км к востоку от с. Брусиловка, в Акмолинской области.', 'SRID=4326;POINT(69.933822 52.959772)', null, '{"source": "osm", "osm": "w320751569", "features": "Площадь около 94 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('09c60341-d624-4469-b861-292dafc1b5bc', private.editorial_id(), 'water_body', '«БейнеуСуСервис» КМК', 'Водохранилище площадью около 6 га в 3 км к юго-западу от г. Бейнеу, в Мангистауской области.', 'SRID=4326;POINT(55.167309 45.301180)', null, '{"source": "osm", "osm": "w583177805", "features": "Площадь около 6 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('5e5a9dc6-bd67-48d2-b510-4d73fe7d6c18', private.editorial_id(), 'water_body', 'Белое', 'Озеро площадью около 1 км² в 5 км к востоку от с. Новопокровка, в Костанайской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(61.220634 53.287174)', null, '{"source": "osm", "osm": "w1412633362", "features": "Площадь около 1 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b14aa034-6ff7-4622-9570-ecd135bbf845', private.editorial_id(), 'water_body', 'Белое озеро (Акмолинская обл.)', 'Озеро площадью около 21 га у с. Белое Озеро, в Акмолинской области.', 'SRID=4326;POINT(70.670833 51.502974)', null, '{"source": "osm", "osm": "w291444326", "features": "Площадь около 21 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('c20a05d3-aa2a-4e1f-aa8a-a4cc5829f88e', private.editorial_id(), 'water_body', 'Белое озеро (СКО)', 'Озеро в 2 км к северо-западу от с. Малое Белое, в Северо-Казахстанской области. Площадь — около 10 км².', 'SRID=4326;POINT(69.257020 54.918319)', null, '{"source": "osm", "osm": "w117302208", "features": "Площадь 10,03 км², длина 4,5 км, ширина 3,2 км, высота над уровнем моря 128,9 м."}', 'public', false, 'published'),
  ('9cc71308-e437-4108-a4af-7f146bf9e53e', private.editorial_id(), 'water_body', 'Белоусовское водохранилище', 'Водохранилище площадью около 41 га у с. Краснопартизанское, в Восточно-Казахстанской области.', 'SRID=4326;POINT(82.551682 50.142901)', null, '{"source": "osm", "osm": "w129447581", "features": "Площадь около 41 га (по данным OpenStreetMap). Вода пресная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('29aacbf5-0e4f-4755-a107-31ce5238fa52', private.editorial_id(), 'water_body', 'Белқопа', 'Пресное озеро у с. Белкопа, в бассейне Иргиза. Площадь — около 14 км². В озеро впадают 9 небольших речек. Замерзает в ноябре, вскрывается в апреле.', 'SRID=4326;POINT(59.612312 50.051333)', null, '{"source": "osm", "osm": "w173137972", "features": "Площадь 14 км², длина 5,6 км, ширина 4 км."}', 'public', false, 'published'),
  ('beb24c34-def7-4199-8530-c5d973e01bca', private.editorial_id(), 'water_body', 'Бесмола', 'Озеро площадью около 95 га в Кызылординской области.', 'SRID=4326;POINT(64.318932 45.907541)', null, '{"source": "osm", "osm": "w698590422", "features": "Площадь около 95 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('70bc7818-8927-443b-aee1-89c546efa66b', private.editorial_id(), 'water_body', 'Бестюбинское водохранилище', 'Горное водохранилище на реке Чарын в Кегенском районе Алматинской области, юго-западнее гор Кулуктау; работает с 2011 года на выработку электроэнергии и орошение. Уровень воды — около 1770 м над морем, плотина высотой 94 м.', 'SRID=4326;POINT(78.896095 43.003032)', null, '{"source": "osm", "osm": "r5191842", "features": "Высота около 1770 м; площадь около 10 км², объём 238 млн м³; плотина 94 м."}', 'public', false, 'published'),
  ('0b2f1ea2-6bf7-4ee5-bfb0-726cddfc0082', private.editorial_id(), 'water_body', 'Беталыс', 'Озеро площадью около 1,8 км² у с. Беталыс, в Карагандинской области.', 'SRID=4326;POINT(75.288794 49.581602)', null, '{"source": "osm", "osm": "w24967096", "features": "Площадь около 1,8 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('3800c131-d25a-4655-b6b5-a42b9e31406f', private.editorial_id(), 'water_body', 'Биликоль', 'Озеро площадью около 72 км² в 4 км к северо-востоку от с. Абдыкадыр, в Жамбылской области.', 'SRID=4326;POINT(70.700425 42.993473)', null, '{"source": "osm", "osm": "w24970926", "features": "Площадь около 72 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('ed0146ae-bed0-4769-9cf2-5edd086a2ebd', private.editorial_id(), 'water_body', 'Биржанколь', 'Озеро площадью около 65 га у с. Биржанколь, в Павлодарской области.', 'SRID=4326;POINT(75.337804 50.821746)', null, '{"source": "osm", "osm": "w122747715", "features": "Площадь около 65 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('86811090-bf5b-4c09-b535-d21eb9800d73', private.editorial_id(), 'water_body', 'Бирказанколь', 'Озеро площадью около 4,7 км² в 5 км к юго-востоку от с. Жангала, в Западно-Казахстанской области. По данным OpenStreetMap, вода солёная, а озеро временами пересыхает. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(50.365412 49.191023)', null, '{"source": "osm", "osm": "w1190100920", "features": "Площадь около 4,7 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('188d4d9a-9f88-46f4-a745-214072aec19b', private.editorial_id(), 'water_body', 'Битикское водохранилище', 'Водохранилище площадью около 28 км² в 19 км к юго-востоку от с. Тегисжол, в Западно-Казахстанской области.', 'SRID=4326;POINT(50.730950 50.367960)', null, '{"source": "osm", "osm": "w328428579", "features": "Площадь около 28 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('ce038ed4-02fb-402b-9bea-980a339e39f5', private.editorial_id(), 'water_body', 'Богатырь', 'Высокогорное озеро в Заилийском Алатау на высоте около 3450 м, в 39 км к юго-востоку от центра Алматы по прямой. На такой высоте озеро свободно ото льда только летом, а погода в горах меняется быстро: идите с прогнозом и скажите близким маршрут. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(77.328526 43.019196)', null, '{"source": "osm", "osm": "w339423133", "features": "Высота около 3450 м."}', 'public', false, 'published'),
  ('a6c07763-5b47-4e38-8bbc-e6ef2f3bacd9', private.editorial_id(), 'water_body', 'Бозшаколь', 'Озеро площадью около 27 км² в 4 км к северо-западу от с. Вишнёвка, в Костанайской области.', 'SRID=4326;POINT(65.913800 53.133481)', null, '{"source": "osm", "osm": "w114823359", "features": "Площадь около 27 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('a00adbe9-e67e-408c-949d-af588b303729', private.editorial_id(), 'water_body', 'Боконское', 'Озеро площадью около 51 га в 4 км к западу от с. Боке, в области Абай.', 'SRID=4326;POINT(81.543461 49.106069)', null, '{"source": "osm", "osm": "w552151197", "features": "Площадь около 51 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('1ca5f58c-3b28-4592-b963-c38a2950a277', private.editorial_id(), 'water_body', 'Болото Сухое', 'Озеро площадью около 1,4 км² в 5 км к северо-западу от с. Полтавка, в Северо-Казахстанской области.', 'SRID=4326;POINT(70.251730 54.860458)', null, '{"source": "osm", "osm": "w176424863", "features": "Площадь около 1,4 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('890379be-3dfd-4b54-af2f-efe65aca8c13', private.editorial_id(), 'water_body', 'Большое Алматинское озеро', 'Горное озеро в Заилийском Алатау на высоте около 2510 м, в 21 км к югу от центра Алматы по прямой, в Иле-Алатауском национальном парке. Длина — около 1,6 км, ширина — до 1 км, глубина — 30–40 м. В марте 2020 года дорогу к озеру закрыли из-за промоин и обвалов, к нему ходили пешком — перед поездкой проверьте, открыта ли она.', 'SRID=4326;POINT(76.985389 43.051042)', null, '{"source": "osm", "osm": "r3427772", "features": "Высота около 2510 м; длина 1,6 км, ширина 0,75–1 км, глубина 30–40 м, площадь 0,9 км²."}', 'public', false, 'published'),
  ('9bda5177-6d04-4a3c-b9a9-a2a2bcc1087b', private.editorial_id(), 'water_body', 'Большое Белое озеро', 'Озеро площадью около 46 га у с. Акимовка, в Акмолинской области.', 'SRID=4326;POINT(70.079940 51.935809)', null, '{"source": "osm", "osm": "w322684002", "features": "Площадь около 46 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('3e1d7863-001b-4671-a05a-0a63988076db', private.editorial_id(), 'water_body', 'Большой Ажбулат', 'Озеро площадью около 124 км² в 18 км к северу от с. Козыкеткен, в Павлодарской области. По данным OpenStreetMap, вода солёная, а озеро временами пересыхает. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(77.406724 53.256733)', null, '{"source": "osm", "osm": "r2248437", "features": "Площадь около 124 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('92052e80-426c-40ed-875b-e12b2d75e114', private.editorial_id(), 'water_body', 'Большой Караколь', 'Озеро площадью около 4,7 км² в 5 км к юго-западу от с. Каражар, в Акмолинской области.', 'SRID=4326;POINT(69.505190 50.442533)', null, '{"source": "osm", "osm": "w49748404", "features": "Площадь около 4,7 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('956dad2b-8bc8-4867-b32c-da27454bd4fb', private.editorial_id(), 'water_body', 'Большой Косколь (с. Косколь, Костанайская обл.)', 'Озеро площадью около 3,5 км² у с. Косколь, в Костанайской области.', 'SRID=4326;POINT(64.839018 53.912198)', null, '{"source": "osm", "osm": "w1531245197", "features": "Площадь около 3,5 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('2ce729c1-d22a-412d-8abf-bf4df7029a0d', private.editorial_id(), 'water_body', 'Большой Косколь (с. Новошумное, Костанайская обл.)', 'Озеро площадью около 9,5 км² в 2 км к западу от с. Новошумное, в Костанайской области.', 'SRID=4326;POINT(62.829669 53.919843)', null, '{"source": "osm", "osm": "w199169752", "features": "Площадь около 9,5 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('f223bc20-bcb4-40d7-b3c4-5e85e9a4e0cd', private.editorial_id(), 'water_body', 'Большой Косколь (СКО)', 'Озеро площадью около 23 км² в 6 км к северо-востоку от с. Акан сере, в Северо-Казахстанской области. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(68.367992 53.378534)', null, '{"source": "osm", "osm": "w249451108", "features": "Площадь около 23 км² (по данным OpenStreetMap). Вода пресная (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('05637034-695a-43c7-9717-f9f4f2971ffb', private.editorial_id(), 'water_body', 'Большой Майлат', 'Озеро площадью около 1,6 км² у с. Луговое, в Костанайской области.', 'SRID=4326;POINT(63.158799 52.688807)', null, '{"source": "osm", "osm": "w150181595", "features": "Площадь около 1,6 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('051fee57-112f-4863-b7eb-b17a7a37d25c', private.editorial_id(), 'water_body', 'Большой Таволжан', 'Озеро площадью около 13 км² в 2 км к северу от с. Таволжан, в Павлодарской области.', 'SRID=4326;POINT(77.455195 52.731597)', null, '{"source": "osm", "osm": "w80738155", "features": "Площадь около 13 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('1f80b7e2-bf03-41f2-878f-3b97cfd20681', private.editorial_id(), 'water_body', 'Большой Талдыколь', 'Озеро в черте Астаны; по данным OpenStreetMap, сезонное — уровень воды сильно меняется за год.', 'SRID=4326;POINT(71.328152 51.113197)', null, '{"source": "osm", "osm": "w23970573"}', 'public', false, 'published'),
  ('496f9f0d-ef3c-4496-acdf-92d535c96c66', private.editorial_id(), 'water_body', 'Большой Теренколь', 'Озеро площадью около 44 км² в 3 км к западу от с. Советское, в Северо-Казахстанской области.', 'SRID=4326;POINT(68.370455 54.036030)', null, '{"source": "osm", "osm": "w114822361", "features": "Площадь около 44 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('ab712b6f-9b65-424b-8ef4-84114c641f88', private.editorial_id(), 'water_body', 'Большой Тересколь', 'Озеро площадью около 6,7 км² у с. Фёдоровка, в Костанайской области.', 'SRID=4326;POINT(65.472321 54.240674)', null, '{"source": "osm", "osm": "w251776417", "features": "Площадь около 6,7 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b7bd02c6-cfb2-4db7-8543-d5a76dce41b0', private.editorial_id(), 'water_body', 'Борлыколь', 'Озеро площадью около 2 га в 6 км к востоку от с. Кара Найза, в Акмолинской области.', 'SRID=4326;POINT(71.572695 52.149655)', null, '{"source": "osm", "osm": "w324494176", "features": "Площадь около 2 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b5381f04-7648-484d-aa56-591b6279e39f', private.editorial_id(), 'water_body', 'Боровской озеро', 'Озеро площадью около 2,3 км² у с. Первомайское, в Костанайской области.', 'SRID=4326;POINT(64.136735 53.798968)', null, '{"source": "osm", "osm": "w121815731", "features": "Площадь около 2,3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('6285a4ea-4597-4043-b417-46c763e6f5b0', private.editorial_id(), 'water_body', 'Бортеколь', 'Озеро площадью около 1,3 км² в 9 км к северу от с. Коржинколь, в Акмолинской области.', 'SRID=4326;POINT(73.389937 51.659628)', null, '{"source": "osm", "osm": "w727371577", "features": "Площадь около 1,3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('ddaf6a03-f0c3-4e31-900a-c3a089b08f34', private.editorial_id(), 'water_body', 'Босколь', 'Озеро в 6 км к западу от с. Босколь, в Костанайской области. Площадь — около 1,8 км².', 'SRID=4326;POINT(61.191733 53.721700)', null, '{"source": "osm", "osm": "w348212651", "features": "Площадь 1,82 км², длина 1,8 км, ширина 1,5 км, высота над уровнем моря 243,2 м."}', 'public', false, 'published'),
  ('23a613c6-38c3-4aee-9292-9dccf5d2ccda', private.editorial_id(), 'water_body', 'Босога', 'Озеро площадью около 9 га в 10 км к югу от с. Донгулек, в области Абай.', 'SRID=4326;POINT(79.155294 50.802553)', null, '{"source": "osm", "osm": "w344268433", "features": "Площадь около 9 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('875b8e0a-b671-4be4-b43f-c538c1a6248b', private.editorial_id(), 'water_body', 'Ботакара водохранилище', 'Водохранилище на реке Уткульсыз в Карагандинской области; объём — около 31 млн м³.', 'SRID=4326;POINT(73.682690 50.093950)', null, '{"source": "osm", "osm": "w43397425", "features": "Объём около 31 млн м³."}', 'public', false, 'published'),
  ('e1ae0fe0-4ce3-42e9-929b-bf54de5ed36c', private.editorial_id(), 'water_body', 'Боткуль', 'Горько-солёное бессточное озеро на границе с Россией: восточная половина — в Западно-Казахстанской области, западная — в Волгоградской. Площадь — 32–65,9 км². Мелкое, в засушливые годы пересыхает. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(46.702179 48.771712)', null, '{"source": "osm", "osm": "r3808353", "features": "Площадь 32–65,9 км², длина 9,6 км, ширина 6,6 км, высота над уровнем моря 2 м. Впадает: Солёная. Вода горько-солёная."}', 'public', false, 'published'),
  ('a59a9707-87a2-4f02-a52f-543f8d8cf3be', private.editorial_id(), 'water_body', 'Бугуньское водохранилище', 'Водохранилище в низовьях реки Бугунь в Туркестанской области, создано в 1967 году для энергетики и орошения. Длина — 13 км, ширина — 6 км, площадь — 65 км². Промысловый улов здесь — около 300 т рыбы в год.', 'SRID=4326;POINT(69.065084 42.739677)', null, '{"source": "osm", "osm": "w39209867", "features": "Длина 13 км, ширина 6 км, площадь 65 км², средняя глубина 6 м, наибольшая — 15 м."}', 'public', false, 'published'),
  ('81f01e15-5821-44fd-b185-1fd3ab7fb161', private.editorial_id(), 'water_body', 'Букынколь', 'Озеро площадью около 10 км² в 7 км к северо-западу от с. Байтак, в Актюбинской области.', 'SRID=4326;POINT(62.047944 48.735359)', null, '{"source": "osm", "osm": "w626139051", "features": "Площадь около 10 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('0d5864a2-206a-4dfd-a9db-2edbaa07da15', private.editorial_id(), 'water_body', 'Буламбайколь', 'Озеро площадью около 72 га в 13 км к северо-востоку от с. Александровка, в Павлодарской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(75.793899 51.019356)', null, '{"source": "osm", "osm": "r1111288", "features": "Площадь около 72 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('22b8b8ae-bfa8-40de-8e51-f66e570cdb35', private.editorial_id(), 'water_body', 'Бухтарминское водохранилище', 'Одно из крупнейших водохранилищ Казахстана — на Иртыше в Восточно-Казахстанской области; в него вошло и озеро Зайсан. Рыбачат в заливах и бухтах. В уловах — лещ, судак, плотва, окунь, щука, линь, язь, сазан, рипус. Зимой ловят со льда; на таком большом водоёме лёд неоднороден — узнайте обстановку у местных рыбаков.', 'SRID=4326;POINT(83.868395 49.011379)', null, '{"source": "osm", "osm": "r1204368", "species": ["bream", "zander", "roach", "perch", "pike", "tench", "common_carp", "ide", "vendace"], "methods": ["shore", "boat", "ice"], "features": "Длина около 425 км, площадь около 5500 км², средняя глубина около 10 м. Берег изрезан заливами и бухтами."}', 'public', false, 'published'),
  ('b30aed36-d4bc-4e62-9e2f-d453dde1d8c8', private.editorial_id(), 'water_body', 'Бухтарминское озеро', 'Озеро площадью около 4,2 км² в 27 км к востоку от с. Аршаты, в Восточно-Казахстанской области, на высоте около 2050 м.', 'SRID=4326;POINT(86.938026 49.289322)', null, '{"source": "osm", "osm": "w215306348", "features": "Площадь около 4,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('646e31b5-ee00-48ec-abf9-9507c29c6870', private.editorial_id(), 'water_body', 'Былкиндык', 'Озеро площадью около 1,1 км² в 7 км к северо-западу от с. Мереке, в Акмолинской области.', 'SRID=4326;POINT(70.250198 51.905565)', null, '{"source": "osm", "osm": "w730067424", "features": "Площадь около 1,1 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b6c06823-099f-4735-9e44-12e15d01d2c2', private.editorial_id(), 'water_body', 'Быструшинское водохранилище', 'Водохранилище площадью около 62 га у с. Коноваловка, в Восточно-Казахстанской области.', 'SRID=4326;POINT(83.582156 50.329339)', null, '{"source": "osm", "osm": "r9493992", "features": "Площадь около 62 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('347b4e1e-3bcf-43ac-85e8-57ed3c9e3525', private.editorial_id(), 'water_body', 'Бөгеткөл көлі', 'Озеро площадью около 4,6 км² в 19 км к северу от с. Жанаоткель, в Жамбылской области.', 'SRID=4326;POINT(70.798484 43.287671)', null, '{"source": "osm", "osm": "w1083722577", "features": "Площадь около 4,6 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('293e7e10-98b9-451e-a2d9-248027ffc2ca', private.editorial_id(), 'water_body', 'Варфоломеевское водохранилище', 'Водохранилище площадью около 5,9 км² у с. Лохматовка, в Западно-Казахстанской области.', 'SRID=4326;POINT(47.998312 50.171196)', null, '{"source": "osm", "osm": "r18855345", "features": "Площадь около 5,9 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('f8435051-b886-4480-89bf-9ecd12aeb517', private.editorial_id(), 'water_body', 'Верхнее Казачье', 'Высокогорное озеро в Заилийском Алатау на высоте около 3300 м, в 33 км к юго-западу от центра Алматы по прямой. На такой высоте озеро свободно ото льда только летом, а погода в горах меняется быстро: идите с прогнозом и скажите близким маршрут.', 'SRID=4326;POINT(76.719989 42.994501)', null, '{"source": "osm", "osm": "w353693549", "features": "Высота около 3300 м."}', 'public', false, 'published'),
  ('36b76eec-63ac-48ec-b2d2-6b9d77aa5bd3', private.editorial_id(), 'water_body', 'Верхнее озеро Сайрам-су', 'Озеро площадью около 3 га в 18 км к северу от с. Пскем, в Туркестанской области, на высоте около 2700 м.', 'SRID=4326;POINT(70.401504 42.090044)', null, '{"source": "osm", "osm": "w141076584", "features": "Площадь около 3 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('cf914941-5e91-496b-a142-bad7a3bf4260', private.editorial_id(), 'water_body', 'Верхнее озеро Тогызак', 'Высокогорное озеро в Заилийском Алатау на высоте около 3700 м, в 33 км к юго-востоку от центра Алматы по прямой. На такой высоте озеро свободно ото льда только летом, а погода в горах меняется быстро: идите с прогнозом и скажите близким маршрут.', 'SRID=4326;POINT(77.200355 43.012028)', null, '{"source": "osm", "osm": "w1081389140", "features": "Высота около 3700 м."}', 'public', false, 'published'),
  ('643753f3-a1ce-4239-aa99-7d65dd649585', private.editorial_id(), 'water_body', 'Верхнее Сильбили', 'Озеро площадью около 1 га в 9 км к югу от с. кордон Дарбаза, в Туркестанской области, на высоте около 2750 м.', 'SRID=4326;POINT(70.465470 42.179183)', null, '{"source": "osm", "osm": "w291218609", "features": "Площадь около 1 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('9d907bdf-db52-4a7a-b6ee-f939d145c99d', private.editorial_id(), 'water_body', 'Верхнетобольское водохранилище', 'Водохранилище на Тоболе в Денисовском районе Костанайской области; вместе с Каратомарским и Амангельдинским входит в каскад на Тоболе. Водится рыба, обычная для Тобола: щука, язь, плотва, карп, налим, лещ, линь, окунь, сиг, рипус.', 'SRID=4326;POINT(62.280070 52.519677)', null, '{"source": "osm", "osm": "r5477169", "species": ["pike", "roach", "common_carp", "bream", "tench", "perch", "ide", "burbot", "whitefish", "vendace"], "methods": ["shore", "boat", "ice"], "features": "Длина около 40 км, площадь около 87 км², средняя глубина около 6 м."}', 'public', false, 'published'),
