  ('03de4aee-a0d6-430e-8280-7071e636e600', private.editorial_id(), 'water_body', 'Жарколь (Акмолинская обл.)', 'Озеро в 8 км к юго-западу от с. Шойындыколь, в Акмолинской области. Площадь — около 21 км².', 'SRID=4326;POINT(67.258383 50.415916)', null, '{"source": "osm", "osm": "w283874243", "features": "Площадь 20,9 км², длина 7,2 км, ширина 4 км, высота над уровнем моря 327,2 м."}', 'public', false, 'published'),
