  ('173a383c-74df-4cab-bb26-b1c27bcd9739', private.editorial_id(), 'water_body', 'Зербулак', 'Озеро площадью около 7 га в 2 км к юго-западу от г. Тараз, в Жамбылской области.', 'SRID=4326;POINT(71.361978 42.882098)', null, '{"source": "osm", "osm": "w382503832", "features": "Площадь около 7 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
