  ('d05ad9fd-3d0f-4379-85e2-59747bf4ab72', private.editorial_id(), 'water_body', 'Каратал', 'Озеро площадью около 1,4 км² в 7 км к югу от с. Неводное, в Павлодарской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(79.200377 51.903046)', null, '{"source": "osm", "osm": "w39355488", "features": "Площадь около 1,4 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('79a9fff9-2dcf-4f1d-803c-573dd515a3d2', private.editorial_id(), 'water_body', 'Каратколь', 'Озеро площадью около 1,9 км² в 4 км к юго-западу от с. Речное, в Костанайской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(64.504601 52.409716)', null, '{"source": "osm", "osm": "w395582081", "features": "Площадь около 1,9 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('c4096470-1384-4178-b99d-6a7ac42bbfec', private.editorial_id(), 'water_body', 'Каратомар', 'Озеро площадью около 1,1 км² у с. Шиликти, в Акмолинской области.', 'SRID=4326;POINT(69.655424 51.505491)', null, '{"source": "osm", "osm": "w322715261", "features": "Площадь около 1,1 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('0afd69c5-e99a-4e3a-ace6-ff033087048f', private.editorial_id(), 'water_body', 'Каратомарское водохранилище', 'Водохранилище на Тоболе в районе Беимбета Майлина Костанайской области, построено в 1966 году, чтобы дать воду Рудному и железорудным месторождениям. С запада в него впадает Аят; вдоль северного берега идут железная дорога Костанай — Житикара и республиканская трасса. Водится рыба, обычная для Тобола: щука, язь, плотва, карп, налим, лещ, линь, окунь, сиг, рипус.', 'SRID=4326;POINT(62.865113 52.799650)', null, '{"source": "osm", "osm": "r5149278", "species": ["pike", "roach", "common_carp", "bream", "tench", "perch", "ide", "burbot", "whitefish", "vendace"], "methods": ["shore", "boat", "ice"], "features": "Длина около 72 км, площадь около 94 км², глубина до 20 м."}', 'public', false, 'published'),
  ('7a6a8f2f-cee0-4bed-a33e-7c73bbcc8c91', private.editorial_id(), 'water_body', 'Караунгур', 'Озеро площадью около 10 км² в 7 км к востоку от с. Дороговка, в Акмолинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(69.684419 52.844733)', null, '{"source": "osm", "osm": "w35146015", "features": "Площадь около 10 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('82348084-a24b-4430-86b3-305312062c8d', private.editorial_id(), 'water_body', 'Каргалинское водохранилище', 'Водохранилище к северо-востоку от Актобе, самое большое из трёх у города: объём — 280 млн м³ (у Актюбинского — 245 млн м³, у Саздинского — 6 млн м³).', 'SRID=4326;POINT(57.790469 50.591749)', null, '{"source": "osm", "osm": "w139118344", "features": "Объём 280 млн м³."}', 'public', false, 'published'),
  ('5150785f-c6d0-4710-8fc1-dbdc5d925584', private.editorial_id(), 'water_body', 'Кармакколь', 'Озеро площадью около 8,1 км² в 3 км к северу от с. Байтак, в Актюбинской области.', 'SRID=4326;POINT(62.079915 48.706866)', null, '{"source": "osm", "osm": "w626139052", "features": "Площадь около 8,1 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('4228a656-9be5-4d9a-8334-6c41d306994d', private.editorial_id(), 'water_body', 'Карнизное', 'Высокогорное озеро в Заилийском Алатау на высоте около 3500 м, в 24 км к югу от центра Алматы по прямой. На такой высоте озеро свободно ото льда только летом, а погода в горах меняется быстро: идите с прогнозом и скажите близким маршрут.', 'SRID=4326;POINT(76.947264 43.020981)', null, '{"source": "osm", "osm": "w230623875", "features": "Высота около 3500 м."}', 'public', false, 'published'),
  ('334cfaba-ff45-43f8-8ead-23d7616c0853', private.editorial_id(), 'water_body', 'Карт Куль', 'Озеро площадью около 2,2 км² в 20 км к юго-западу от с. Жамбыл, в Павлодарской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(75.551190 52.946594)', null, '{"source": "osm", "osm": "w553409261", "features": "Площадь около 2,2 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('dc5ea30c-4337-4922-aded-5b7260ad2fa8', private.editorial_id(), 'water_body', 'Каскабулакколь', 'Озеро площадью около 7,5 км² в 6 км к юго-востоку от с. Каскабулак, в области Абай. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(79.935213 49.532630)', null, '{"source": "osm", "osm": "w1546921417", "features": "Площадь около 7,5 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('9231d7fc-c8fd-4cec-9aa8-f185db8f5b17', private.editorial_id(), 'water_body', 'Каскат', 'Озеро площадью около 2 км² в 13 км к юго-востоку от с. Жанажол, в Акмолинской области.', 'SRID=4326;POINT(73.127164 51.808029)', null, '{"source": "osm", "osm": "w183130934", "features": "Площадь около 2 км² (по данным OpenStreetMap). Вода пресная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('d7e77b63-540b-4e10-8248-82cb96d656c2', private.editorial_id(), 'water_body', 'Катпанколь', 'Озеро площадью около 32 га в 3 км к западу от с. Шункыркудук, в Карагандинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(74.910779 49.322054)', null, '{"source": "osm", "osm": "w1300718996", "features": "Площадь около 32 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('358efe97-d2f9-4cfd-9c32-533d670f9cc4', private.editorial_id(), 'water_body', 'Катынколь', 'Озеро площадью около 8,1 км² в 17 км к северо-востоку от с. Коктас, в Карагандинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(75.147800 49.733825)', null, '{"source": "osm", "osm": "w24977916", "features": "Площадь около 8,1 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b01acef1-0a13-48f0-a63e-ef889187fdf8', private.editorial_id(), 'water_body', 'Кашкансу', 'Озеро площадью около 76 га в 14 км к востоку от с. Бекбауыл, в Кызылординской области.', 'SRID=4326;POINT(62.114944 45.997975)', null, '{"source": "osm", "osm": "w263370436", "features": "Площадь около 76 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('9158c8db-2c20-4f7b-bccb-80702e13983f', private.editorial_id(), 'water_body', 'Кедровое (ВКО)', 'Озеро площадью около 7 га в 27 км к юго-востоку от с. Поперечное, в Восточно-Казахстанской области, на высоте около 1900 м.', 'SRID=4326;POINT(84.147836 50.297108)', null, '{"source": "osm", "osm": "w169480078", "features": "Площадь около 7 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('ec0e3c0d-d2b1-4868-9338-b30599628e6f', private.editorial_id(), 'water_body', 'Кедровое (г. Ульба, ВКО)', 'Озеро площадью около 2 га в 13 км к юго-востоку от г. Ульба, в Восточно-Казахстанской области, на высоте около 1800 м.', 'SRID=4326;POINT(83.464802 50.158488)', null, '{"source": "osm", "osm": "w188640183", "features": "Площадь около 2 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('db7037e4-3cac-48ef-98bf-48d26a84a293', private.editorial_id(), 'water_body', 'Кельте', 'Озеро площадью около 2 км² в 8 км к северо-западу от с. Аккиик, в области Жетісу.', 'SRID=4326;POINT(77.191960 46.295176)', null, '{"source": "osm", "osm": "w310023758", "features": "Площадь около 2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('90c6218a-178d-4d07-b127-17d6d54e057d', private.editorial_id(), 'water_body', 'Кемеркол', 'Озеро площадью около 1,9 км² у с. Кемеркол, в Акмолинской области.', 'SRID=4326;POINT(70.506088 52.067246)', null, '{"source": "osm", "osm": "w150289423", "features": "Площадь около 1,9 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('5a25017d-1d77-4782-b9b7-76322609ed44', private.editorial_id(), 'water_body', 'Кемерколь', 'Бессточное слабосолоноватое озеро в западных отрогах Курчумского хребта, в 9 км к юго-западу от с. Кыстау-Курчум, в Восточно-Казахстанской области. Площадь — около 1,7 км²; наибольшая глубина — 15,5 м. Водятся елец, плотва, сазан, карп и карась. Дно песчаное; с мая по сентябрь уровень падает больше чем на метр.', 'SRID=4326;POINT(84.462734 48.604416)', null, '{"source": "osm", "osm": "w303194162", "species": ["other", "roach", "common_carp", "crucian_carp"], "features": "Площадь 1,72 км², длина 2,3 км, ширина 1,1 км, наибольшая глубина 15,5 м, высота над уровнем моря 839,7 м."}', 'public', false, 'published'),
  ('34c62529-6657-46b5-be13-23d24c2c7c7f', private.editorial_id(), 'water_body', 'Кенгирское водохранилище', 'Водохранилище на реке Кенгир (1952 год), на его южном берегу — г. Жезказган. Площадь — около 37 км²; наибольшая глубина — 25 м. Длинное и узкое: около 33 км при ширине 1,6 км. Вода идёт на энергетику и орошение.', 'SRID=4326;POINT(67.757917 47.907001)', null, '{"source": "osm", "osm": "r2268101", "features": "Площадь 37 км², длина 33 км, ширина 1,6 км, наибольшая глубина 25 м."}', 'public', false, 'published'),
  ('f232e7f5-8192-4b21-b1bd-b96b60069ac7', private.editorial_id(), 'water_body', 'Кендирли', 'Озеро площадью около 20 км² в 8 км к западу от с. Наталовка, в Костанайской области.', 'SRID=4326;POINT(63.070334 52.601785)', null, '{"source": "osm", "osm": "r7256328", "features": "Площадь около 20 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('cdb2222c-175d-4c7c-934b-d2d4a59bf81b', private.editorial_id(), 'water_body', 'Кенебайколь', 'Озеро площадью около 11 км² в 16 км к востоку от с. Озёрное, в Костанайской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(63.036353 53.240166)', null, '{"source": "osm", "osm": "w151688984", "features": "Площадь около 11 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('be73996d-ae5c-43ad-b049-34630e09bb93', private.editorial_id(), 'water_body', 'Кенжеколь', 'Озеро площадью около 6 га в 4 км к юго-западу от с. Кенжеколь, в Павлодарской области.', 'SRID=4326;POINT(76.997970 52.155547)', null, '{"source": "osm", "osm": "w1448204685", "features": "Площадь около 6 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('6adb5c42-79fd-4b22-8eb9-e607494aa355', private.editorial_id(), 'water_body', 'Кенколь', 'Озеро площадью около 16 га в 19 км к северо-западу от с. Акжал, в Карагандинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(75.363796 49.788592)', null, '{"source": "osm", "osm": "w428432188", "features": "Площадь около 16 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('af7aede1-1914-4e5b-8206-7f4876cfe5e2', private.editorial_id(), 'water_body', 'Кербулак', 'Водоём в Алматинской области, в 110 км к северу от центра Алматы по прямой, на высоте около 620 м.', 'SRID=4326;POINT(77.297288 44.194299)', null, '{"source": "osm", "osm": "w592070271"}', 'public', false, 'published'),
  ('0aa4d1a1-3719-424c-b4f5-6d1e729df400', private.editorial_id(), 'water_body', 'Керденколь', 'Озеро площадью около 11 км² в 11 км к северо-западу от с. Теристанбалы, в области Абай. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(80.713419 50.170179)', null, '{"source": "osm", "osm": "w47895818", "features": "Площадь около 11 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('91ae04d7-6831-4f33-9c1b-83e9fd4884d7', private.editorial_id(), 'water_body', 'Кировское водохранилище', 'Водохранилище на реке Кушум в Акжаикском и Байтерекском районах Западно-Казахстанской области, создано в 1967 году для энергетики и орошения. Длина — 21,6 км, ширина — 4 км; мелкое — средняя глубина 1,6 м.', 'SRID=4326;POINT(50.945655 50.668917)', null, '{"source": "osm", "osm": "w298643162", "features": "Длина 21,6 км, ширина 4 км, площадь 39,1 км², средняя глубина 1,6 м, наибольшая — около 7 м."}', 'public', false, 'published'),
  ('6498e704-6b49-458b-b699-b20bcb641844', private.editorial_id(), 'water_body', 'Кишкенежарма озеро', 'Озеро площадью около 1,1 км² у с. Борки, в Северо-Казахстанской области.', 'SRID=4326;POINT(69.750279 54.635771)', null, '{"source": "osm", "osm": "w1220982697", "features": "Площадь около 1,1 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('afaf3378-10cd-4a5f-825f-a83b3c47a8c0', private.editorial_id(), 'water_body', 'Кишкенеколь (с. Жарсуат, Акмолинская обл.)', 'Озеро площадью около 46 га в 3 км к юго-востоку от с. Жарсуат, в Акмолинской области.', 'SRID=4326;POINT(69.816791 51.741494)', null, '{"source": "osm", "osm": "w321325331", "features": "Площадь около 46 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('ae4ebbb5-feb2-4e09-9492-3ca48aff84b4', private.editorial_id(), 'water_body', 'Кишкенеколь (с. Коржинколь, Акмолинская обл.)', 'Озеро площадью около 27 га в 10 км к северу от с. Коржинколь, в Акмолинской области.', 'SRID=4326;POINT(73.399885 51.675015)', null, '{"source": "osm", "osm": "w727371405", "features": "Площадь около 27 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('644f6791-8828-4554-a787-0c9121eb1a0b', private.editorial_id(), 'water_body', 'Кияколь', 'Озеро площадью около 2,2 км² в 6 км к юго-востоку от с. село Жумата Шанина, в Павлодарской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(75.816831 50.370599)', null, '{"source": "osm", "osm": "r19268468", "features": "Площадь около 2,2 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('774c36a4-975b-4d74-85d0-330a26f6827d', private.editorial_id(), 'water_body', 'Кобейтуз розовое озеро', 'Солёное бессточное озеро, известное розовым цветом воды, в 17 км к северо-западу от с. Уленты, в Акмолинской области. Солёность — около 334 г/л, рыба в такой воде не живёт. Розовым озеро бывает не каждый год.', 'SRID=4326;POINT(73.547140 51.735672)', null, '{"source": "osm", "osm": "w183130938", "features": "Высота над уровнем моря 253 м."}', 'public', false, 'published'),
  ('f542dea1-447b-4942-a1d9-298ac0f52004', private.editorial_id(), 'water_body', 'Кожаколь', 'Озеро площадью около 20 км² в 3 км к северу от с. Коныртубек, в Акмолинской области.', 'SRID=4326;POINT(69.171263 50.918590)', null, '{"source": "osm", "osm": "w23099085", "features": "Площадь около 20 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('2bc7286f-9d99-4681-93ff-a140ecd17080', private.editorial_id(), 'water_body', 'Койбагар', 'Бессточное мелкое озеро на Тургайском плато, в 5 км к востоку от с. Карасу. Площадь — около 96 км²; средняя глубина — 1,6 м. Рамсарское угодье (с 2009 года) в составе Койбагар-Тюнтюгурской системы озёр. Площадь сильно меняется с уровнем воды, глубина обычно 1,3–1,5 м. Водится 8–10 видов рыб, чаще всего — щука и окунь.', 'SRID=4326;POINT(65.592224 52.607229)', null, '{"source": "osm", "osm": "w42178830", "species": ["pike", "perch"], "features": "Площадь 96 км², длина 17,8 км, ширина 9,1 км, средняя глубина 1,6 м, высота над уровнем моря 202 м. Впадает: Карасу."}', 'public', false, 'published'),
  ('2453fd0f-9b60-4d26-bfff-ac1f3daa5704', private.editorial_id(), 'water_body', 'Кокколь', 'Высокогорное озеро на высоте около 2400 м в Восточно-Казахстанской области; в 6,5 км по прямой — водопад Кокколь.', 'SRID=4326;POINT(86.751727 49.709513)', null, '{"source": "osm", "osm": "w333922110", "features": "Высота около 2400 м."}', 'public', false, 'published'),
  ('0f8833bd-f08e-4b7a-af72-3c929e066bcc', private.editorial_id(), 'water_body', 'Кокозек', 'Озеро площадью около 49 га в черте Алматы.', 'SRID=4326;POINT(76.771693 43.306454)', null, '{"source": "osm", "osm": "w23650857", "features": "Площадь около 49 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('0655bc54-a466-4587-9bd5-a7b74b464996', private.editorial_id(), 'water_body', 'Кокпекти', 'Озеро площадью около 14 км² в 8 км к западу от с. Аккабак, в Костанайской области.', 'SRID=4326;POINT(63.166059 53.221794)', null, '{"source": "osm", "osm": "r19149855", "features": "Площадь около 14 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('91103aa3-98a2-4e5a-b807-929e7ee6112a', private.editorial_id(), 'water_body', 'Коксарайское водохранилище', 'Водохранилище справа от Сырдарьи в Туркестанской области, в 160 км ниже Шардаринского. Построено в 2008–2011 годах для орошения и защиты от паводков — принимает сбросы Шардаринской ГЭС.', 'SRID=4326;POINT(68.494732 42.406329)', null, '{"source": "osm", "osm": "r2195379", "features": "Площадь около 470 км², объём до 3 млрд м³; дамба длиной 44,7 км."}', 'public', false, 'published'),
  ('563b3e07-3b30-4e38-b2e6-c3dca10d5caa', private.editorial_id(), 'water_body', 'Коктенколь', 'Озеро площадью около 14 км² в 9 км к юго-западу от с. Коктенколь, в Карагандинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(72.107814 48.517535)', null, '{"source": "osm", "osm": "w537630844", "features": "Площадь около 14 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('dc52bbb9-022b-41d0-a35f-04b27c5f66f3', private.editorial_id(), 'water_body', 'Коктерекколь', 'Озеро площадью около 6,2 км² у с. Салтанат, в Западно-Казахстанской области. По данным OpenStreetMap, вода солёная, а озеро временами пересыхает. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(50.409711 49.020311)', null, '{"source": "osm", "osm": "w1017960487", "features": "Площадь около 6,2 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('1041fc85-d256-40ac-a18e-6ce5165a35bf', private.editorial_id(), 'water_body', 'Кокуйрум', 'Озеро площадью около 6 га в 18 км к северо-западу от с. Ойгаинг, в Туркестанской области, на высоте около 2500 м.', 'SRID=4326;POINT(70.783362 42.309671)', null, '{"source": "osm", "osm": "w139829635", "features": "Площадь около 6 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('5e673510-3288-4d3c-be62-35db540a8c2a', private.editorial_id(), 'water_body', 'Кокуйрым', 'Озеро площадью около 5,5 км² в Павлодарской области.', 'SRID=4326;POINT(76.671767 51.267231)', null, '{"source": "osm", "osm": "w1547389888", "features": "Площадь около 5,5 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('69120ac7-ad5a-43b9-b830-6df952ae4186', private.editorial_id(), 'water_body', 'Колшик Куль', 'Озеро площадью около 77 га в 3 км к югу от с. Приозёрное, в Северо-Казахстанской области.', 'SRID=4326;POINT(66.549328 53.727562)', null, '{"source": "osm", "osm": "w553239276", "features": "Площадь около 77 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('40ae2ee7-1673-4c94-863a-20a2d4b30254', private.editorial_id(), 'water_body', 'Кольжарма', 'Озеро площадью около 8,2 км² в 4 км к северу от с. Нура, в Актюбинской области.', 'SRID=4326;POINT(62.323980 48.924550)', null, '{"source": "osm", "osm": "w208011940", "features": "Площадь около 8,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('3e2ab054-2ab0-471e-acb1-f7ebf58d55b5', private.editorial_id(), 'water_body', 'Кольсай №1', 'Нижнее из трёх Кольсайских озёр — в Кегенском районе, в национальном парке «Көлсай көлдері», в 115 км к востоку от центра Алматы по прямой. Высота — около 1820 м, длина — около 1 км, ширина — 400 м, глубина — до 39 м. Вокруг — лес из тяньшанской ели; в озёрах водится радужная форель. Ловить рыбу в национальном парке можно только по его правилам.', 'SRID=4326;POINT(78.325098 42.985849)', null, '{"source": "osm", "osm": "w117881869", "species": ["rainbow_trout"], "features": "Высота около 1820 м; длина около 1 км, ширина 400 м, глубина до 39 м."}', 'public', false, 'published'),
  ('dfb7fed9-7b09-4222-a716-7123883cadcf', private.editorial_id(), 'water_body', 'Кольсай №2', 'Среднее Кольсайское озеро (Мынжылкы) — самое большое из трёх, на высоте около 2250 м, в национальном парке «Көлсай көлдері» Кегенского района, в 117 км к востоку от центра Алматы по прямой. Вокруг — лес из тяньшанской ели; в озёрах водится радужная форель. Ловить рыбу в национальном парке можно только по его правилам.', 'SRID=4326;POINT(78.326682 42.932693)', null, '{"source": "osm", "osm": "w237179072", "species": ["rainbow_trout"], "features": "Высота около 2250 м; самое большое из трёх Кольсайских озёр."}', 'public', false, 'published'),
  ('87bea92c-922d-44c8-8534-75db8cec5756', private.editorial_id(), 'water_body', 'Кольшик', 'Озеро площадью около 37 га у с. Макпал, в Акмолинской области.', 'SRID=4326;POINT(70.700964 52.600329)', null, '{"source": "osm", "osm": "w302695694", "features": "Площадь около 37 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
