  ('352de562-d398-4837-a547-c56192c8ba16', private.editorial_id(), 'water_body', 'Малая Ембулатовка', 'Водохранилище площадью около 77 га в 2 км к юго-западу от с. Рожково, в Западно-Казахстанской области.', 'SRID=4326;POINT(52.293499 51.647809)', null, '{"source": "osm", "osm": "w329826840", "features": "Площадь около 77 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('5c76d33a-4c29-4063-af7c-ddc36db96d61', private.editorial_id(), 'water_body', 'Малкар', 'Озеро у с. Москворецкое, в Северо-Казахстанской области. Площадь — около 1,3 км²; наибольшая глубина — 1,5 м.', 'SRID=4326;POINT(66.370134 53.693823)', null, '{"source": "osm", "osm": "w553239831", "features": "Площадь 1,26 км², длина 2,2 км, ширина до 0,9 км, наибольшая глубина 1,5 м, высота над уровнем моря 169,8 м."}', 'public', false, 'published'),
  ('1a113da6-567b-4025-a4c9-2f6de7f7c932', private.editorial_id(), 'water_body', 'Малое Аральское море', 'Северная часть бывшего Аральского моря в Кызылординской области, которую питает Сырдарья. После постройки Кокаральской плотины вода стала менее солёной, в море вернулись 22 вида рыб, а улов вырос с сотен килограммов в начале 1990-х до тысяч тонн в год.', 'SRID=4326;POINT(60.632641 46.436042)', null, '{"source": "osm", "osm": "r8728779", "features": "Солоноватое: минерализация около 8–9 ‰ (была до 30 ‰ в конце 1980-х)."}', 'public', false, 'published'),
  ('d8bba036-0dbf-48fc-bddb-87fccd237f33', private.editorial_id(), 'water_body', 'Малое Кызылоба', 'Озеро площадью около 3,2 км² в 4 км к северо-востоку от с. Борык, в Западно-Казахстанской области.', 'SRID=4326;POINT(50.372343 49.594571)', null, '{"source": "osm", "osm": "w301908900", "features": "Площадь около 3,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('17c1aab2-8535-42ca-a760-e9051666838b', private.editorial_id(), 'water_body', 'Малоульбинское водохранилище', 'Горное водохранилище на реке Малая Ульба в черте Риддера (Восточно-Казахстанская область), на высоте около 1570 м. Построено в 1930-х годах для Ульбинской ГЭС и введено в 1938 году; сейчас даёт воду Риддеру и Лениногорскому каскаду ГЭС. Длина — 5 км, ширина — до 3 км, средняя глубина — 13,4 м, наибольшая — 31,5 м.', 'SRID=4326;POINT(83.845285 50.166869)', null, '{"source": "osm", "osm": "r12345347", "features": "Высота около 1570 м; длина 5 км, ширина до 3 км, площадь 5,2–6,5 км², средняя глубина 13,4 м, наибольшая — 31,5 м."}', 'public', false, 'published'),
