  ('c40c88e5-63b1-4c71-ac9f-8e7ba02c1351', private.editorial_id(), 'water_body', 'Озеро Жантеке', 'Озеро площадью около 100 га у с. Жантеке, в Акмолинской области.', 'SRID=4326;POINT(70.162087 50.790668)', null, '{"source": "osm", "osm": "w244818907", "features": "Площадь около 100 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('e696217e-9d2e-4cd0-9885-13918dd518b1', private.editorial_id(), 'water_body', 'Озеро Жаныбекшалкар', 'Озеро площадью около 21 км² в 4 км к западу от с. Садырбай, в Акмолинской области.', 'SRID=4326;POINT(70.288240 50.591346)', null, '{"source": "osm", "osm": "w275602783", "features": "Площадь около 21 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('febf4f29-2c03-4de9-912e-5364b6eab9de', private.editorial_id(), 'water_body', 'Озеро Жаркен', 'Озеро в 4 км к западу от с. Жаркен, в Северо-Казахстанской области. Площадь — около 6,8 км². Входит в перечень рыбохозяйственных водоёмов местного значения; на озере есть озёрно-товарное рыбоводное хозяйство — о правилах лова спросите на месте.', 'SRID=4326;POINT(66.995437 54.033409)', null, '{"source": "osm", "osm": "w536894451", "features": "Площадь 6,77 км², длина 3,5 км, ширина 2,3 км, высота над уровнем моря 160,3 м."}', 'public', false, 'published'),
  ('80955c3e-649c-4caf-b01b-d0ec53596a64', private.editorial_id(), 'water_body', 'Озеро Жарколь (с. Аккабак, Костанайская обл.)', 'Озеро площадью около 18 км² в 4 км к западу от с. Аккабак, в Костанайской области.', 'SRID=4326;POINT(63.227296 53.194556)', null, '{"source": "osm", "osm": "w151688985", "features": "Площадь около 18 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b84224ee-6a23-40fb-88ea-a20e7f07d092', private.editorial_id(), 'water_body', 'Озеро Жарколь (с. Жарколь, Костанайская обл.)', 'Озеро площадью около 5,3 км² у с. Жарколь, в Костанайской области.', 'SRID=4326;POINT(64.800165 53.996410)', null, '{"source": "osm", "osm": "w1529371203", "features": "Площадь около 5,3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b0efde36-403a-46e2-bae4-ed5ca03142c9', private.editorial_id(), 'water_body', 'Озеро Жарколь (с. Приозёрное, Костанайская обл.)', 'Озеро площадью около 2,8 км² у с. Приозёрное, в Костанайской области.', 'SRID=4326;POINT(62.688179 53.620894)', null, '{"source": "osm", "osm": "w114562285", "features": "Площадь около 2,8 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('d6844cfc-9412-4bac-a193-708ac650143e', private.editorial_id(), 'water_body', 'Озеро Жарлыколь', 'Озеро площадью около 13 км² в 9 км к юго-западу от с. Жангызкудук, в Акмолинской области.', 'SRID=4326;POINT(70.983051 50.605117)', null, '{"source": "osm", "osm": "w180051024", "features": "Площадь около 13 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('860304bf-5bc9-4b19-a491-c8a8b0d79fc9', private.editorial_id(), 'water_body', 'Озеро Жартас', 'Озеро площадью около 1,3 км² в 10 км к востоку от с. Жарлы, в Карагандинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(75.239891 49.498160)', null, '{"source": "osm", "osm": "w24977996", "features": "Площадь около 1,3 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('a012f585-847b-43a0-a283-8a007af2d0f6', private.editorial_id(), 'water_body', 'Озеро Жасыл', 'Озеро площадью около 26 га в 6 км к востоку от с. Бибакан, в области Жетісу, на высоте около 1100 м.', 'SRID=4326;POINT(81.049888 45.771922)', null, '{"source": "osm", "osm": "w292269318", "features": "Площадь около 26 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('a8303aec-d0f4-4de8-8706-16817f8b89fb', private.editorial_id(), 'water_body', 'Озеро Жаткамбай', 'Озеро площадью около 12 км² в 6 км к северо-западу от с. Аккабак, в Костанайской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(63.228252 53.239744)', null, '{"source": "osm", "osm": "w151688986", "features": "Площадь около 12 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('2caea494-9f83-4555-bc91-fa2227400d6c', private.editorial_id(), 'water_body', 'Озеро Жекеколь', 'Озеро площадью около 1,1 км² у с. Благовещенка, в Северо-Казахстанской области.', 'SRID=4326;POINT(66.965039 54.361960)', null, '{"source": "osm", "osm": "w252858156", "features": "Площадь около 1,1 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('28794329-cf5c-48e5-86df-f5889936a42a', private.editorial_id(), 'water_body', 'Озеро Желтенькое', 'Озеро площадью около 1,2 км² в 6 км к западу от с. Щучье, в Северо-Казахстанской области.', 'SRID=4326;POINT(68.409344 55.157137)', null, '{"source": "osm", "osm": "w782595223", "features": "Площадь около 1,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('e5fd45ef-b028-4002-a3fb-755795de4d08', private.editorial_id(), 'water_body', 'Озеро Жетикколь', 'Озеро площадью около 44 га в 2 км к северо-западу от с. Новотроицкое, в Костанайской области.', 'SRID=4326;POINT(61.506218 53.927916)', null, '{"source": "osm", "osm": "w335035385", "features": "Площадь около 44 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('ed34740f-0101-4727-a9ad-8fbe8c524f5e', private.editorial_id(), 'water_body', 'Озеро Жиланды (Костанайская обл.)', 'Озеро площадью около 81 га в 3 км к северо-западу от с. Магнай, в Костанайской области.', 'SRID=4326;POINT(61.272115 53.905931)', null, '{"source": "osm", "osm": "w348212634", "features": "Площадь около 81 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('27774e5b-9d86-4102-adbf-430643d908ce', private.editorial_id(), 'water_body', 'Озеро Жиланды (обл. Абай)', 'Озеро площадью около 1,1 км² в 5 км к югу от с. Жыланды, в области Абай. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(80.270877 47.646330)', null, '{"source": "osm", "osm": "w38226195", "features": "Площадь около 1,1 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('9f1c03a2-de00-47ef-96c5-4da60d62c714', private.editorial_id(), 'water_body', 'Озеро Жолдыозек', 'Озеро в 8 км к северо-западу от с. Амангельды, в Северо-Казахстанской области. Площадь — около 12 км².', 'SRID=4326;POINT(69.407020 54.392033)', null, '{"source": "osm", "osm": "w208763283", "features": "Площадь 12 км², длина 6,2 км, ширина 3 км, высота над уровнем моря 126,6 м."}', 'public', false, 'published'),
  ('22a9d26a-dae6-49b0-90d5-5f5373c9609c', private.editorial_id(), 'water_body', 'Озеро Жыландышалкар', 'Озеро площадью около 11 км² в 6 км к востоку от с. Уялы, в Акмолинской области.', 'SRID=4326;POINT(70.420741 50.662923)', null, '{"source": "osm", "osm": "w275602784", "features": "Площадь около 11 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('03298a56-19ce-4391-be81-1d84a76d1feb', private.editorial_id(), 'water_body', 'Озеро Жылы', 'Озеро площадью около 4 га в 26 км к северо-востоку от с. Рахмановские Ключи, в Восточно-Казахстанской области, на высоте около 2000 м.', 'SRID=4326;POINT(86.677161 49.737564)', null, '{"source": "osm", "osm": "w334088921", "features": "Площадь около 4 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('26035cce-f75d-4b77-b108-7c6f392a6179', private.editorial_id(), 'water_body', 'Озеро Жынгылды', 'Озеро площадью около 17 км² в 15 км к северо-западу от с. Атыгай, в Павлодарской области. По данным OpenStreetMap, это водоём-охладитель, вода пресная.', 'SRID=4326;POINT(75.374135 51.866417)', null, '{"source": "osm", "osm": "w27167085", "features": "Площадь около 17 км² (по данным OpenStreetMap). Водоём-охладитель, вода пресная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('ef6b0737-a286-438c-9834-69201a94833a', private.editorial_id(), 'water_body', 'Озеро Забочное', 'Озеро площадью около 1,1 км² в 3 км к северо-западу от с. Соколовка, в Северо-Казахстанской области.', 'SRID=4326;POINT(69.171680 55.132161)', null, '{"source": "osm", "osm": "w28870684", "features": "Площадь около 1,1 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('1c76f71b-ab38-4de0-9f8b-7c43ce9a4d89', private.editorial_id(), 'water_body', 'Озеро Зайсан', 'Большое озеро на востоке Казахстана, в котловине между Алтаем и Тарбагатаем; после постройки Бухтарминской ГЭС стало частью Бухтарминского водохранилища. Водятся судак, щука, налим, окунь, язь, линь, лещ и карась. Лёд стоит с ноября до конца апреля.', 'SRID=4326;POINT(83.648238 48.079293)', null, '{"source": "osm", "osm": "r35913", "species": ["zander", "pike", "perch", "tench", "bream", "crucian_carp", "burbot", "ide"], "methods": ["shore", "boat", "ice"], "features": "Берега местами заросли тростником."}', 'public', false, 'published'),
  ('2ded6187-cd34-40a6-b21c-219e9de3a2cb', private.editorial_id(), 'water_body', 'Озеро Зарослое', 'Озеро у с. Зарослое, в Северо-Казахстанской области. Площадь — около 1,2 км². Входит в перечень рыбохозяйственных водоёмов местного значения.', 'SRID=4326;POINT(70.217352 55.064567)', null, '{"source": "osm", "osm": "w234171547", "features": "Площадь 1,19 км², длина 1,3 км, ширина 1,2 км, высота над уровнем моря 129,2 м."}', 'public', false, 'published'),
  ('40dbee99-2b56-431d-a35f-423ab8d76dc5', private.editorial_id(), 'water_body', 'Озеро Зелёное', 'Озеро площадью около 9 га в 19 км к югу от с. Аршаты, в Восточно-Казахстанской области, на высоте около 2350 м.', 'SRID=4326;POINT(86.638672 49.126574)', null, '{"source": "osm", "osm": "w656610232", "features": "Площадь около 9 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('f1a28b10-7e6c-47f8-bbef-98b469ffa4c9', private.editorial_id(), 'water_body', 'Озеро Зеренда', 'Озеро вдоль северо-восточных склонов Зерендинских гор в Акмолинской области; на берегу — село Зеренда. Входит в национальный парк «Кокшетау» и Зерендинский заказник. Мелкое: средняя глубина — 4,2 м, наибольшая — 6,8 м.', 'SRID=4326;POINT(69.114181 52.923556)', null, '{"source": "osm", "osm": "w35143868", "features": "Длина 5,3 км, ширина до 3,5 км, площадь 9,6 км², средняя глубина 4,2 м, наибольшая — 6,8 м; высота 371 м."}', 'public', false, 'published'),
  ('15cec15f-67b5-4462-acff-ac787b2d1289', private.editorial_id(), 'water_body', 'Озеро Ивана Васильевича', 'Озеро площадью около 1,2 км² в 6 км к юго-востоку от с. Журавлёвка, в Акмолинской области.', 'SRID=4326;POINT(69.990613 51.895914)', null, '{"source": "osm", "osm": "w279689847", "features": "Площадь около 1,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('bd0a554e-4fce-4b68-9a66-2dede9d7ad6a', private.editorial_id(), 'water_body', 'Озеро Изколь', 'Озеро площадью около 25 га в 3 км к северу от с. Граничное, в Костанайской области.', 'SRID=4326;POINT(65.020718 54.237485)', null, '{"source": "osm", "osm": "w1529160754", "features": "Площадь около 25 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('a4bcbc1f-655e-434e-beeb-baa1ed4ae8cb', private.editorial_id(), 'water_body', 'Озеро Ильмень Сажанский', 'Озеро площадью около 16 га в 3 км к северо-востоку от с. Даулеткерей, в Атырауской области.', 'SRID=4326;POINT(49.390260 46.632710)', null, '{"source": "osm", "osm": "w389176293", "features": "Площадь около 16 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('d79c32c0-3c6a-4e31-ad3b-8d5a99067457', private.editorial_id(), 'water_body', 'Озеро Ильчибек', 'Озеро площадью около 1,8 км² в 7 км к северо-западу от с. Граничное, в Костанайской области.', 'SRID=4326;POINT(64.926883 54.238870)', null, '{"source": "osm", "osm": "w1529046856", "features": "Площадь около 1,8 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('22f00ab8-612c-49f9-bd13-f9fddd9c7b85', private.editorial_id(), 'water_body', 'Озеро Имантау', 'Озеро в Айыртауском районе Северо-Казахстанской области, вытянуто с северо-запада на юго-восток; на юго-восточном берегу — село Имантау. Длина — 13,1 км, ширина — 4,8 км, средняя глубина — 5,7 м. Водятся чебак, язь, окунь, щука, зеркальный карп, карась.', 'SRID=4326;POINT(68.256560 53.022875)', null, '{"source": "osm", "osm": "r947706", "species": ["roach", "ide", "perch", "pike", "common_carp", "crucian_carp"], "features": "Длина 13,1 км, ширина 4,8 км, средняя глубина 5,7 м, наибольшая — более 10 м."}', 'public', false, 'published'),
  ('1b510576-0134-4886-a08c-ec31d6ee71d1', private.editorial_id(), 'water_body', 'Озеро Исей', 'Озеро площадью около 48 км² в 7 км к востоку от с. Каражар, в Акмолинской области.', 'SRID=4326;POINT(69.637346 50.496514)', null, '{"source": "osm", "osm": "w23099078", "features": "Площадь около 48 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('3c5008a8-bb97-46cf-b287-448c08f878d0', private.editorial_id(), 'water_body', 'Озеро Иснал', 'Озеро площадью около 91 га в 4 км к югу от с. Коктерек, в Северо-Казахстанской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(69.456106 54.457051)', null, '{"source": "osm", "osm": "w208763284", "features": "Площадь около 91 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('6db70fc0-63a7-4679-8c3f-e8ab76cf6145', private.editorial_id(), 'water_body', 'Озеро Иссык', 'Завальное озеро в Иссыкском ущелье Заилийского Алатау, на высоте около 1710 м, в 44 км к востоку от центра Алматы по прямой. В июле 1963 года сель разрушил естественную плотину, и озеро почти исчезло; к 1990-м плотину восстановили, и водоём снова наполнился, но в 2020 году после запуска ГЭС уровень воды сильно упал. С 2019 года озеро и плотина в частном доверительном управлении, проезд туристического транспорта закрыт — уточняйте доступ и состояние озера перед поездкой.', 'SRID=4326;POINT(77.485601 43.253496)', null, '{"source": "osm", "osm": "w27106049", "features": "Высота около 1710 м; озеро образовано горным обвалом 8–10 тыс. лет назад."}', 'public', false, 'published'),
  ('7e3528c7-a77b-4e9e-a0d5-022272e75a25', private.editorial_id(), 'water_body', 'Озеро Итемген', 'Бессточное мелкое озеро, в 9 км к северо-западу от с. Жалгызкарагай, в Акмолинской области. Площадь — около 57 км²; наибольшая глубина — 3,5 м. С юга впадает река Аксуат. Уровень сильно меняется: в 1931–1933 годах озеро пересыхало.', 'SRID=4326;POINT(71.102390 52.346297)', null, '{"source": "osm", "osm": "w304249142", "features": "Площадь 57,4 км², длина 11,5 км, ширина 7,4 км, наибольшая глубина 3,5 м (средняя 1 м), высота над уровнем моря 294,6 м. Впадает: Аксуат."}', 'public', false, 'published'),
