  ('6e42c111-6495-4223-aeb8-b6c809aaa24f', private.editorial_id(), 'water_body', 'Озеро Щучье', 'Озеро в Бурабайском районе Акмолинской области: на юго-западном берегу — город Щучинск, до посёлка Боровое — 12 км. Самое глубокое из озёр курортной зоны «Бурабай» — до 31–40 м; почти со всех сторон лес. Название — от обилия щуки. Водятся щука, окунь, чебак, сиг, пелядь, рипус, ряпушка, линь, судак, карп; есть раки.', 'SRID=4326;POINT(70.212064 52.982227)', null, '{"source": "osm", "osm": "r953632", "species": ["pike", "perch", "roach", "whitefish", "vendace", "tench", "zander", "common_carp"], "features": "Длина 7,5 км, ширина 3 км, площадь 19,6 км², глубина до 31–40 м (средняя 18,5 м); высота 395 м."}', 'public', false, 'published'),
