  ('8d1bce6f-55e4-4b17-9c14-aa766095d70c', private.editorial_id(), 'water_body', 'Подбелковое', 'Горное озеро у подножия Вышеивановского белка, высшей точки Ивановского хребта, в 24 км к востоку от Риддера, на высоте около 1900 м. Второе название — Радоновое: по неофициальным данным, в озеро попадает вода из заброшенной штольни.', 'SRID=4326;POINT(83.844591 50.315131)', null, '{"source": "osm", "osm": "w166154177", "features": "Высота над уровнем моря 1906,5 м."}', 'public', false, 'published'),
  ('fb6ce6f7-1628-49c9-8ad1-ab2021893585', private.editorial_id(), 'water_body', 'Покровский пруд', 'Водохранилище площадью около 48 га в 4 км к юго-востоку от с. Детдом, в Костанайской области.', 'SRID=4326;POINT(64.236713 53.860799)', null, '{"source": "osm", "osm": "w151688978", "features": "Площадь около 48 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('6cfb2750-4ca4-421d-99ea-261a656ae99d', private.editorial_id(), 'water_body', 'Половинное', 'Озеро площадью около 64 га в 6 км к востоку от с. Дубровное, в Северо-Казахстанской области.', 'SRID=4326;POINT(68.190759 54.809422)', null, '{"source": "osm", "osm": "w117398947", "features": "Площадь около 64 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('556ab30a-1a66-4d84-a4dc-19dd061dd436', private.editorial_id(), 'water_body', 'Приютские озёра', 'Озёра в Алматинской области, в 20 км к северу от центра Алматы по прямой, на высоте около 650 м.', 'SRID=4326;POINT(76.901729 43.411705)', null, '{"source": "osm", "osm": "r19120221"}', 'public', false, 'published'),
  ('896472e0-361a-46b7-9819-f9b24a347a90', private.editorial_id(), 'water_body', 'Пруд Жарык', 'Озеро площадью около 1,7 км² в 10 км к юго-востоку от с. Тауыш-2, в Костанайской области.', 'SRID=4326;POINT(64.071846 49.933663)', null, '{"source": "osm", "osm": "w1137797674", "features": "Площадь около 1,7 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('c092c806-ce8e-456e-8778-9a3bfe5196a2', private.editorial_id(), 'water_body', 'Пруд Мантык', 'Водохранилище площадью около 43 га у с. Сулу коль, в Западно-Казахстанской области.', 'SRID=4326;POINT(52.152316 51.656141)', null, '{"source": "osm", "osm": "w144707406", "features": "Площадь около 43 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('38ee919a-90b5-4360-8b48-b5d883028ec3', private.editorial_id(), 'water_body', 'Птичник', 'Озеро площадью около 20 га в 3 км к юго-западу от с. Молодежное, в Костанайской области.', 'SRID=4326;POINT(63.772878 53.787733)', null, '{"source": "osm", "osm": "w206146302", "features": "Площадь около 20 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('bc3f0789-6531-4808-b4f0-4ba152148b1d', private.editorial_id(), 'water_body', 'Пятнистое', 'Высокогорное озеро в Заилийском Алатау на высоте около 3300 м, в 62 км к юго-западу от центра Алматы по прямой. На такой высоте озеро свободно ото льда только летом, а погода в горах меняется быстро: идите с прогнозом и скажите близким маршрут.', 'SRID=4326;POINT(76.314519 42.918967)', null, '{"source": "osm", "osm": "w397783295", "features": "Высота около 3300 м."}', 'public', false, 'published'),
  ('b18af734-4e27-48f8-86ee-f73d0f87892e', private.editorial_id(), 'water_body', 'Равновесия', 'Озеро площадью около 2 га в 22 км к северо-востоку от с. Рахмановские Ключи, в Восточно-Казахстанской области, на высоте около 2300 м.', 'SRID=4326;POINT(86.668543 49.700680)', null, '{"source": "osm", "osm": "w840045439", "features": "Площадь около 2 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('07c324c9-c486-450e-ba7d-600c2975c63b', private.editorial_id(), 'water_body', 'Разливанское', 'Озеро площадью около 5 га в 14 км к юго-востоку от с. Поперечное, в Восточно-Казахстанской области, на высоте около 2000 м.', 'SRID=4326;POINT(83.945394 50.308620)', null, '{"source": "osm", "osm": "w166154153", "features": "Площадь около 5 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('470a77d7-86a4-4bcc-b4fb-308999ffd276', private.editorial_id(), 'water_body', 'Райское озеро', 'Озеро площадью около 10 га в 11 км к западу от с. Кураксу, в области Жетісу. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(78.126141 46.031920)', null, '{"source": "osm", "osm": "w1181805809", "features": "Площадь около 10 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('d6bae8cd-dc49-4f00-a5ee-6d9a7e24b768', private.editorial_id(), 'water_body', 'Райхан', 'Озеро площадью около 10 га в 12 км к западу от с. Кураксу, в области Жетісу. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(78.122461 46.036803)', null, '{"source": "osm", "osm": "w1181805808", "features": "Площадь около 10 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('09e1ccd3-9f3d-430d-a295-b5d0bec99321', private.editorial_id(), 'water_body', 'Рассыпное', 'Озеро площадью около 8 га в 14 км к югу от с. Поперечное, в Восточно-Казахстанской области, на высоте около 2200 м.', 'SRID=4326;POINT(83.841680 50.281140)', null, '{"source": "osm", "osm": "w166154154", "features": "Площадь около 8 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('e546d9c2-eb3c-47a6-8212-66e39e851c23', private.editorial_id(), 'water_body', 'Рахмановское', 'Озеро на реке Арасан в Катон-Карагайском районе, в 2 км к юго-востоку от с. Рахмановские Ключи, в Восточно-Казахстанской области, на высоте около 1800 м. В 80 м ниже по течению — Рахмановские ключи: 12 родников лечебной воды вытекают из гранитной скалы; известны с XVIII века.', 'SRID=4326;POINT(86.536717 49.520808)', null, '{"source": "osm", "osm": "w117813624", "features": "Высота над уровнем моря 1760 м."}', 'public', false, 'published'),
  ('430b898a-a8d0-4b22-8cf7-8d3bc9aedb6c', private.editorial_id(), 'water_body', 'Речное озеро', 'Озеро площадью около 22 км² в 3 км к югу от с. Амречье, в Костанайской области.', 'SRID=4326;POINT(65.756066 54.095800)', null, '{"source": "osm", "osm": "w285455252", "features": "Площадь около 22 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('fa560933-149c-40fd-a528-13a2e9d1c4cc', private.editorial_id(), 'water_body', 'Рудничное', 'Озеро площадью около 6,8 км² в 4 км к юго-западу от с. Шалкар, в Карагандинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(74.858159 50.229390)', null, '{"source": "osm", "osm": "r5992325", "features": "Площадь около 6,8 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('700f5f08-4f8f-4628-8d1e-4ae7a64dc11a', private.editorial_id(), 'water_body', 'Рыбное', 'Озеро площадью около 14 га в 14 км к югу от с. Поперечное, в Восточно-Казахстанской области, на высоте около 2100 м.', 'SRID=4326;POINT(83.855986 50.289608)', null, '{"source": "osm", "osm": "w166154141", "features": "Площадь около 14 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
