  ('ce88e8d8-a52e-4531-9eff-b8fb8501626f', private.editorial_id(), 'water_body', 'Сабакты', 'Озеро площадью около 3,2 км² в 2 км к западу от с. Алгабас, в Акмолинской области.', 'SRID=4326;POINT(69.380628 51.556936)', null, '{"source": "osm", "osm": "w274957834", "features": "Площадь около 3,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('519e3352-bf63-44f8-a822-bc163df306c7', private.editorial_id(), 'water_body', 'Сабындыкөл', 'Озеро площадью около 7,5 км² у с. Баянаул, в Павлодарской области.', 'SRID=4326;POINT(75.709843 50.779673)', null, '{"source": "osm", "osm": "w30434304", "features": "Площадь около 7,5 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('bb5d878c-21e7-450e-881b-b92f3a12c9df', private.editorial_id(), 'water_body', 'Сагырбай', 'Озеро площадью около 9,8 км² в 2 км к западу от с. Кыркопа, в Западно-Казахстанской области. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(50.312499 49.384397)', null, '{"source": "osm", "osm": "r15666390", "features": "Площадь около 9,8 км² (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('7609b973-21f8-466b-bb29-a2ce4b982861', private.editorial_id(), 'water_body', 'Садовское озеро', 'Озеро в Западно-Казахстанской области; по данным OpenStreetMap, по нему можно ходить на лодке, в том числе моторной.', 'SRID=4326;POINT(51.354466 51.268930)', null, '{"source": "osm", "osm": "w172479785"}', 'public', false, 'published'),
  ('5758aaeb-541b-4bbd-b39e-292cb2d8db0d', private.editorial_id(), 'water_body', 'Садырколь', 'Озеро площадью около 68 га в 3 км к востоку от с. Алгабас, в Восточно-Казахстанской области.', 'SRID=4326;POINT(82.591815 49.451064)', null, '{"source": "osm", "osm": "w24949285", "features": "Площадь около 68 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('a6830b77-0966-4eab-88f0-365949ac8c92', private.editorial_id(), 'water_body', 'Саздинское водохранилище', 'Небольшое водохранилище к юго-западу от Актобе, объём — около 6 млн м³; самое маленькое из трёх водохранилищ у города.', 'SRID=4326;POINT(57.124562 50.221389)', null, '{"source": "osm", "osm": "w203340613", "features": "Объём около 6 млн м³."}', 'public', false, 'published'),
  ('0b916712-48e4-4d86-ab0b-940cd4aadfcf', private.editorial_id(), 'water_body', 'Сайран', 'Городское водохранилище на Большой Алматинке — между улицами Толе би, Садовникова, Варламова и проспектом Абая. Средняя глубина — около 12 м, наибольшая — 18 м. В 2022–2026 годах водохранилище и зону отдыха вокруг реконструировали.', 'SRID=4326;POINT(76.864801 43.243409)', null, '{"source": "osm", "osm": "w208488825", "features": "Средняя глубина около 12 м, наибольшая — 18 м; объём 2,3 млн м³."}', 'public', false, 'published'),
  ('cde3e506-6536-43d0-9df3-ae2628b76cd1', private.editorial_id(), 'water_body', 'Самарбай', 'Озеро площадью около 5 км² в 11 км к северо-востоку от с. Узункольское, в Акмолинской области.', 'SRID=4326;POINT(69.999394 51.021825)', null, '{"source": "osm", "osm": "w320376755", "features": "Площадь около 5 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('a6a30404-c7c0-4896-b24b-a1fba921fbd1', private.editorial_id(), 'water_body', 'Самаркандское водохранилище', 'Водохранилище на Нуре (1941 год), на южном и западном берегах — г. Темиртау. Площадь — около 84 км²; наибольшая глубина — 17 м. Второе название — Темиртауское. Воду берут Карметкомбинат и электростанции города.', 'SRID=4326;POINT(73.040837 50.099644)', null, '{"source": "osm", "osm": "r18089961", "features": "Площадь 84 км², длина 20 км, ширина 7 км, наибольшая глубина 17 м (средняя 3,25 м), высота над уровнем моря 489 м."}', 'public', false, 'published'),
  ('1b8916a5-f2fa-43da-be0b-f452e42b1959', private.editorial_id(), 'water_body', 'Сангасы', 'Озеро площадью около 3,2 км² в Акмолинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(73.425751 52.182769)', null, '{"source": "osm", "osm": "w321246397", "features": "Площадь около 3,2 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('efc12277-2b88-4314-8bcd-a54e3fbb6c45', private.editorial_id(), 'water_body', 'Саранколь', 'Озеро площадью около 49 га в 12 км к западу от с. Коянбай, в области Абай.', 'SRID=4326;POINT(79.144524 51.556106)', null, '{"source": "osm", "osm": "w256057674", "features": "Площадь около 49 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
