  ('ef934427-baec-4043-ad12-f729f903a550', private.editorial_id(), 'water_body', 'Сарыколь (с. Уялы, Акмолинская обл.)', 'Озеро площадью около 2,9 км² в 5 км к югу от с. Уялы, в Акмолинской области.', 'SRID=4326;POINT(69.364242 52.520016)', null, '{"source": "osm", "osm": "w320693842", "features": "Площадь около 2,9 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
