  ('13e65870-6467-4821-83bc-e9bf873518a5', private.editorial_id(), 'water_body', 'Сарыкопа', 'Бессточное солёное озеро в Тургайской ложбине, в 8 км к северу от с. Кумшик, в Костанайской области. Площадь — около 184 км². Состоит из нескольких плёсов: одни опресняются, другие копят соль. Впадают реки Сарыозен и Теке. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(64.167377 50.374567)', null, '{"source": "osm", "osm": "r284031", "features": "Площадь 184 км², длина 27,6 км, ширина 13,2 км, высота над уровнем моря 101,2 м. Впадает: Сарыозен, Теке."}', 'public', false, 'published'),
  ('0c870c0d-be3e-42af-870a-10e638508e8d', private.editorial_id(), 'water_body', 'Сарымойын', 'Озеро площадью около 4,8 км² в 13 км к востоку от с. Жамбыл, в Костанайской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(64.437721 51.668202)', null, '{"source": "osm", "osm": "r7283333", "features": "Площадь около 4,8 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('dc43302e-20fa-4132-9608-f762155bc229', private.editorial_id(), 'water_body', 'Сасыкколь (Кызылординская обл.)', 'Озеро площадью около 29 га в 3 км к северо-западу от с. Буланбайбауы, в Кызылординской области.', 'SRID=4326;POINT(66.578583 43.918097)', null, '{"source": "osm", "osm": "w810642322", "features": "Площадь около 29 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('feee8214-6268-4681-9e3b-30931a547b6a', private.editorial_id(), 'water_body', 'Сасыкколь (обл. Абай)', 'Проточное озеро в Балхаш-Алакольской котловине, к северо-западу от Алаколя, в 15 км к юго-востоку от с. Сагат, в области Абай. Площадь — около 736 км²; наибольшая глубина — 4,7 м. Водятся сазан, судак, маринка и окунь. Берега низкие, в тростнике.', 'SRID=4326;POINT(80.927078 46.620169)', null, '{"source": "osm", "osm": "r1660939", "species": ["common_carp", "zander", "marinka", "perch"], "features": "Площадь 736 км², длина 49,6 км, ширина 20 км, наибольшая глубина 4,7 м (средняя 3,3 м), высота над уровнем моря 350 м. Впадает: Тентек, Каракол, Ай. Вытекает: Топкая."}', 'public', false, 'published'),
  ('02e45564-2970-42ea-aac5-6905ecb30f98', private.editorial_id(), 'water_body', 'Сасыкпай', 'Водохранилище в Алматинской области, в 54 км к западу от центра Алматы по прямой, на высоте около 820 м.', 'SRID=4326;POINT(76.281543 43.239101)', null, '{"source": "osm", "osm": "w409304070"}', 'public', false, 'published'),
  ('b4560375-7f14-4814-ac61-f0db32243f52', private.editorial_id(), 'water_body', 'Сасым', 'Озеро площадью около 29 га в 3 км к северу от с. Жананегиз, в Карагандинской области.', 'SRID=4326;POINT(75.516246 49.499956)', null, '{"source": "osm", "osm": "w428379341", "features": "Площадь около 29 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('644e2e8f-3106-47b5-939d-93b52e2aa220', private.editorial_id(), 'water_body', 'Сасықкөл', 'Озеро площадью около 5 км² в 18 км к северу от с. Талдыбулак, в области Улытау.', 'SRID=4326;POINT(71.452059 49.006650)', null, '{"source": "osm", "osm": "w1387733023", "features": "Площадь около 5 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('0e6b0b9b-292d-4ac6-9b0c-74d1bff1d23c', private.editorial_id(), 'water_body', 'Саумалколь', 'Озеро площадью около 9,1 км² в 11 км к востоку от с. Акши, в Павлодарской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(74.351204 50.706830)', null, '{"source": "osm", "osm": "w424950248", "features": "Площадь около 9,1 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('3b2e2e7b-8f66-424a-a908-c5e4596a820b', private.editorial_id(), 'water_body', 'Саумалкуль', 'Озеро площадью около 1,5 км² в 19 км к востоку от с. Улгайсын, в Актюбинской области.', 'SRID=4326;POINT(60.559207 49.513367)', null, '{"source": "osm", "osm": "w206380115", "features": "Площадь около 1,5 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('62f8ede8-14a4-4ce3-9e02-32de3e3b2e08', private.editorial_id(), 'water_body', 'Сауманколь', 'Озеро площадью около 6,2 км² в 14 км к западу от с. Теректы, в Карагандинской области.', 'SRID=4326;POINT(75.989046 50.051617)', null, '{"source": "osm", "osm": "w154698116", "features": "Площадь около 6,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('e0dd6ef9-0956-40c1-8979-3cb9d2ef9367', private.editorial_id(), 'water_body', 'Селетинское водохранилище', 'Водохранилище на реке Селеты в Ерейментауском районе Акмолинской области, примерно в 53 км от Степногорска. Водятся карась, карп, плотва, щука, окунь, лещ и линь.', 'SRID=4326;POINT(72.718081 52.136840)', null, '{"source": "osm", "osm": "r3546733", "species": ["crucian_carp", "common_carp", "roach", "pike", "perch", "bream", "tench"], "methods": ["shore", "boat", "ice"], "features": "На водохранилище есть острова."}', 'public', false, 'published'),
  ('6e9fa76a-e63e-4266-942b-49221dadd35a', private.editorial_id(), 'water_body', 'Селетытениз', 'Бессточное горько-солёное озеро на дне обширной впадины, в 15 км к югу от с. Коктерек, в Северо-Казахстанской области. Площадь — 750–777 км²; наибольшая глубина — 3,2 м. Река Силеты доходит до озера только в половодье. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(73.203310 53.342331)', null, '{"source": "osm", "osm": "w44884982", "features": "Площадь 750–777 км², длина 64,7 км, ширина 22,1 км, наибольшая глубина 3,2 м (средняя 2 м), высота над уровнем моря 64,7 м. Впадает: Силети."}', 'public', false, 'published'),
  ('8c46023b-21e5-4a03-910c-e923bede8505', private.editorial_id(), 'water_body', 'Семиозёрка озеро', 'Озеро площадью около 1,2 км² в 6 км к северо-западу от с. Калиновка, в Северо-Казахстанской области.', 'SRID=4326;POINT(66.380659 54.628742)', null, '{"source": "osm", "osm": "w1221006179", "features": "Площадь около 1,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('8751e034-c74e-4eee-93a4-3786063ec4c9', private.editorial_id(), 'water_body', 'Сергеевское водохранилище', 'Водохранилище на Есиле (Ишиме) к югу от Сергеевки — районного центра в Северо-Казахстанской области. Зимой замерзает; что ловится — расскажите в отчёте о рыбалке.', 'SRID=4326;POINT(67.258169 53.697766)', null, '{"source": "osm", "osm": "r5446880", "methods": ["shore", "boat", "ice"], "features": "Длина около 75 км, площадь около 117 км², средняя глубина около 6 м."}', 'public', false, 'published'),
