  ('56baaeb7-f9ae-4fad-bec8-cd3e2875b45f', private.editorial_id(), 'water_body', 'Сулуколь', 'Озеро площадью около 3,4 км² в 9 км к северо-западу от с. Аккудык, в Западно-Казахстанской области.', 'SRID=4326;POINT(54.286783 50.484856)', null, '{"source": "osm", "osm": "w269802590", "features": "Площадь около 3,4 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('e06e79f2-f420-4a76-8b56-d4fc55ecdc37', private.editorial_id(), 'water_body', 'Сулуколь (с. Каракамыс, ЗКО)', 'Озеро площадью около 1,2 км² в 7 км к востоку от с. Каракамыс, в Западно-Казахстанской области.', 'SRID=4326;POINT(53.255649 49.315402)', null, '{"source": "osm", "osm": "w398727748", "features": "Площадь около 1,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b4ed9e76-79ba-42a6-b82c-3728ca422d49', private.editorial_id(), 'water_body', 'Сункаркия', 'Озеро площадью около 60 га в Акмолинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(73.616412 52.159226)', null, '{"source": "osm", "osm": "w321246399", "features": "Площадь около 60 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('4fc3da7a-3a7e-4c5f-a3a3-33813c19dcd8', private.editorial_id(), 'water_body', 'Сусинген', 'Озеро площадью около 57 га в 15 км к юго-востоку от с. Бургулюк, в Туркестанской области, на высоте около 1900 м.', 'SRID=4326;POINT(70.164172 42.048754)', null, '{"source": "osm", "osm": "w268110574", "features": "Площадь около 57 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('d2b5ca87-f3d1-4bf1-a3d2-dfcbc1ee1885', private.editorial_id(), 'water_body', 'Сфагновые озера', 'Высокогорные озёра в Заилийском Алатау на высоте около 3200 м, в 57 км к востоку от центра Алматы по прямой. На такой высоте озёра свободны ото льда только летом, а погода в горах меняется быстро: идите с прогнозом и скажите близким маршрут.', 'SRID=4326;POINT(77.635113 43.158241)', null, '{"source": "osm", "osm": "r16918875", "features": "Высота около 3200 м."}', 'public', false, 'published'),
  ('a2dc13b6-880a-452c-b594-312464600fc4', private.editorial_id(), 'water_body', 'Сүлүколь', 'Озеро площадью около 1,2 км² у с. Селеты, в Павлодарской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(73.899489 52.954870)', null, '{"source": "osm", "osm": "w423577432", "features": "Площадь около 1,2 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('9560baf8-f098-4f23-b640-0e9963bb6627', private.editorial_id(), 'water_body', 'Табанказы', 'Озеро площадью около 3,3 км² в 7 км к юго-востоку от с. Каражар, в Акмолинской области.', 'SRID=4326;POINT(69.599840 50.430900)', null, '{"source": "osm", "osm": "w49748423", "features": "Площадь около 3,3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('c5c81959-2dfd-4d3e-9afa-8b6212ee3170', private.editorial_id(), 'water_body', 'Тазловановское озеро', 'Озеро площадью около 11 га в 4 км к северу от с. Киевское, в Акмолинской области.', 'SRID=4326;POINT(67.701864 52.084149)', null, '{"source": "osm", "osm": "w1383763669", "features": "Площадь около 11 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('cabe6cf1-73e9-484b-af48-e1935638d1a9', private.editorial_id(), 'water_body', 'Талап', 'Водоём в Алматинской области, в 67 км к северо-западу от центра Алматы по прямой, на высоте около 600 м.', 'SRID=4326;POINT(76.310077 43.630851)', null, '{"source": "osm", "osm": "w22742200"}', 'public', false, 'published'),
  ('ca25261b-ed7d-436f-b9d7-6fc328e6af11', private.editorial_id(), 'water_body', 'Талапское', 'Озеро площадью около 54 га в 4 км к востоку от с. Журавлёвка, в Акмолинской области.', 'SRID=4326;POINT(70.003827 51.949863)', null, '{"source": "osm", "osm": "w322684139", "features": "Площадь около 54 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b592e90b-f0d6-4661-becc-cbae15e01f00', private.editorial_id(), 'water_body', 'Талдыколь (Акмолинская обл.)', 'Озеро площадью около 6,3 км² у с. Воробьёвка, в Акмолинской области.', 'SRID=4326;POINT(69.863099 51.893778)', null, '{"source": "osm", "osm": "w150169938", "features": "Площадь около 6,3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('35a30eac-a94f-47f7-854b-6010e921af68', private.editorial_id(), 'water_body', 'Талдыколь (Павлодарская обл.)', 'Озеро площадью около 1,2 км² в 11 км к востоку от с. Майкобе, в Павлодарской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(75.929806 51.266723)', null, '{"source": "osm", "osm": "w123700935", "features": "Площадь около 1,2 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('a50ccfc2-315f-409d-bd33-48c342994cb0', private.editorial_id(), 'water_body', 'Талкынколь', 'Озеро площадью около 99 га у с. Бирлик, в Акмолинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(69.475329 51.626672)', null, '{"source": "osm", "osm": "w322720293", "features": "Площадь около 99 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('f5b71806-63ab-4fdb-b312-755d9b8623d6', private.editorial_id(), 'water_body', 'Таран', 'Водоём в Алматинской области, в 56 км к западу от центра Алматы по прямой, на высоте около 730 м. Прежнее название — Аксенгирское.', 'SRID=4326;POINT(76.266666 43.342738)', null, '{"source": "osm", "osm": "w22742196"}', 'public', false, 'published'),
  ('4b02a880-dc59-4793-94fe-d58a0b6fe019', private.editorial_id(), 'water_body', 'Тарелочка', 'Озеро площадью около 5 га в 5 км к западу от г. Костанай, в Костанайской области.', 'SRID=4326;POINT(63.563544 53.220658)', null, '{"source": "osm", "osm": "w118446698", "features": "Площадь около 5 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('cc24fc8e-0bc4-4792-8761-4e0c265aa100', private.editorial_id(), 'water_body', 'Тарылган', 'Озеро площадью около 1,1 км² в 19 км к северо-востоку от с. Акоба, в Западно-Казахстанской области.', 'SRID=4326;POINT(47.533137 49.608837)', null, '{"source": "osm", "osm": "w407519600", "features": "Площадь около 1,1 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('30c0276e-5b01-4a90-943d-f00d80051d58', private.editorial_id(), 'water_body', 'Таскол', 'Озеро площадью около 61 га в 9 км к северо-востоку от с. Комекбаева, в Кызылординской области.', 'SRID=4326;POINT(63.253850 44.914100)', null, '{"source": "osm", "osm": "w698516767", "features": "Площадь около 61 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('edbaab09-b688-4fb9-bffe-6967947addf0', private.editorial_id(), 'water_body', 'Тасколь', 'Озеро площадью около 8 га в 4 км к юго-востоку от с. Беталыс, в Карагандинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(75.324590 49.547559)', null, '{"source": "osm", "osm": "w199776320", "features": "Площадь около 8 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('1d652db3-b7ff-49a5-9736-860021472b96', private.editorial_id(), 'water_body', 'Тасонгар', 'Озеро площадью около 12 км² в 7 км к юго-востоку от с. Кыркопа, в Западно-Казахстанской области. По данным OpenStreetMap, вода солёная, а озеро временами пересыхает. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(50.407853 49.333524)', null, '{"source": "osm", "osm": "w1017960479", "features": "Площадь около 12 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('849726b9-b5b7-483d-8c29-5c23b7474754', private.editorial_id(), 'water_body', 'Тасоткельское водохранилище', 'Одно из крупнейших водохранилищ Жамбылской области — на реке Шу у посёлка Тасоткель, введено в 1974 году. Вода идёт на полив Шуского и Мойынкумского районов; в 2013 году к плотине пристроили небольшую ГЭС.', 'SRID=4326;POINT(73.961240 43.365169)', null, '{"source": "osm", "osm": "w38857985", "features": "Проектный объём 620 млн м³; в 2010 году использовалось около 320 млн м³."}', 'public', false, 'published'),
  ('21bda179-da29-41a5-8163-dd2b46ab2989', private.editorial_id(), 'water_body', 'Тендик', 'Озеро площадью около 8 км² в 6 км к западу от с. Муса Шорманов, в Павлодарской области.', 'SRID=4326;POINT(74.688973 50.647590)', null, '{"source": "osm", "osm": "w539627433", "features": "Площадь около 8 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('28ebdd21-0495-4238-9054-7596ac383547', private.editorial_id(), 'water_body', 'Теплое', 'Старица площадью около 31 га в 5 км к югу от с. Дарьинское, в Западно-Казахстанской области.', 'SRID=4326;POINT(51.728454 51.318215)', null, '{"source": "osm", "osm": "r15506935", "features": "Площадь около 31 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('8e87e059-231f-419b-a349-f64c4a27fb2d', private.editorial_id(), 'water_body', 'Теренколь (Павлодарская обл.)', 'Озеро площадью около 70 га в 3 км к северо-западу от с. Мынколь, в Павлодарской области.', 'SRID=4326;POINT(76.585801 53.772989)', null, '{"source": "osm", "osm": "w615321985", "features": "Площадь около 70 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('07f4c775-af80-4695-b955-cd94aad1cfb2', private.editorial_id(), 'water_body', 'Теренколь (СКО)', 'Озеро площадью около 4,4 км² у с. Заря, в Северо-Казахстанской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(68.560366 53.514999)', null, '{"source": "osm", "osm": "w536296152", "features": "Площадь около 4,4 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('751768d2-0f3b-4f3c-8157-fab4dd397141', private.editorial_id(), 'water_body', 'Территория водокачки', 'Водохранилище площадью около 2 га у с. Камысты, в Костанайской области.', 'SRID=4326;POINT(61.789247 51.971044)', null, '{"source": "osm", "osm": "w453452441", "features": "Площадь около 2 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('9464a9bb-5e72-4ce7-938b-55f0e9c9fbc0', private.editorial_id(), 'water_body', 'Терс-Ащыбулакское водохранилище', 'Водохранилище в Жамбылской области на реках Терис, Бахаты и Сасыкбулак, введено в 1963 году. Длина — около 18 км, ширина — до 6 км, площадь — 13 км², глубина — до 21 м.', 'SRID=4326;POINT(70.890013 42.685454)', null, '{"source": "osm", "osm": "w22377317", "features": "Длина около 18 км, ширина до 6 км, площадь 13 км², глубина до 21 м, объём 150 млн м³."}', 'public', false, 'published'),
  ('2da83e65-398a-4645-8bb1-e8f8f793804c', private.editorial_id(), 'water_body', 'Тимофеева', 'Высокогорное озеро в Заилийском Алатау на высоте около 3600 м, в 27 км к югу от центра Алматы по прямой. На такой высоте озеро свободно ото льда только летом, а погода в горах меняется быстро: идите с прогнозом и скажите близким маршрут.', 'SRID=4326;POINT(77.064373 43.011202)', null, '{"source": "osm", "osm": "w1064846059", "features": "Высота около 3600 м."}', 'public', false, 'published'),
  ('5c6b7c62-ee69-47c2-897d-a4550700f2e4', private.editorial_id(), 'water_body', 'Тогай', 'Озеро площадью около 61 га в 4 км к юго-западу от с. Корпебай, в Восточно-Казахстанской области.', 'SRID=4326;POINT(82.121608 49.628865)', null, '{"source": "osm", "osm": "w45181762", "features": "Площадь около 61 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b7542792-911a-466e-a8e8-7d90c6d93988', private.editorial_id(), 'water_body', 'Тойганколь', 'Озеро площадью около 1,7 км² в 16 км к востоку от с. Жанажол, в Акмолинской области.', 'SRID=4326;POINT(73.202155 51.849488)', null, '{"source": "osm", "osm": "w183130936", "features": "Площадь около 1,7 км² (по данным OpenStreetMap). Вода пресная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('f1fc8dfe-4d52-4307-a824-eb90e17033b0', private.editorial_id(), 'water_body', 'Топкое Селитровое озеро', 'Озеро площадью около 14 га в 4 км к востоку от с. Садыкащи, в Павлодарской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(78.858385 52.038996)', null, '{"source": "osm", "osm": "w884022117", "features": "Площадь около 14 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('08f2e5fe-9e1b-47ca-a180-8867d8a14b61', private.editorial_id(), 'water_body', 'Торткара', 'Озеро площадью около 1,2 км² в 5 км к востоку от с. Алгабас, в Восточно-Казахстанской области.', 'SRID=4326;POINT(82.619054 49.448015)', null, '{"source": "osm", "osm": "w24949284", "features": "Площадь около 1,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('0beb1fec-f556-4895-b22e-83c14979fbca', private.editorial_id(), 'water_body', 'Торткулак', 'Озеро площадью около 1,6 км² в 8 км к северу от г. Айтеке би, в Кызылординской области.', 'SRID=4326;POINT(62.127140 45.910898)', null, '{"source": "osm", "osm": "w698505855", "features": "Площадь около 1,6 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('6760f656-5fb0-4873-bc67-3cfff916160a', private.editorial_id(), 'water_body', 'Торыат', 'Вода солёная, но не горькая - с фильтром можно было бы ей воспользоваться - на берегу много следов косуль, которые сюда приходят на водопой.', 'SRID=4326;POINT(76.187166 51.491928)', null, '{"source": "osm", "osm": "w403244532"}', 'public', false, 'published'),
  ('5b2b6669-f94b-4f6b-8ab3-ca216f5e4fe6', private.editorial_id(), 'water_body', 'Тоғай', 'Озеро площадью около 2 га в 6 км к юго-западу от с. Корпебай, в Восточно-Казахстанской области.', 'SRID=4326;POINT(82.097064 49.627916)', null, '{"source": "osm", "osm": "w1547587895", "features": "Площадь около 2 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('c31efe27-0e05-4e2e-b858-50dec3abf437', private.editorial_id(), 'water_body', 'Травное озеро', 'Озеро в 4 км к северо-западу от с. Новокаменка, в Северо-Казахстанской области. Площадь — около 3,8 км².', 'SRID=4326;POINT(68.938022 54.731403)', null, '{"source": "osm", "osm": "w117063069", "features": "Площадь 3,8 км², длина 2,5 км, ширина 1,9 км, высота над уровнем моря 99,1 м."}', 'public', false, 'published'),
  ('00f180fb-2c3e-4926-8693-c723d061e793', private.editorial_id(), 'water_body', 'Троицкое водохранилище', 'Водохранилище на реке Уй у Троицкой ГРЭС, на границе с Челябинской областью России (1960 год). Площадь — около 11 км². Водятся щука, окунь, лещ, судак, чебак, плотва, язь, красноперка, карп, белый амур, толстолобик и канальный сом. В 2018 году в водохранилище выпустили сазана.', 'SRID=4326;POINT(61.713326 54.021169)', null, '{"source": "osm", "osm": "w105999264", "species": ["pike", "perch", "bream", "zander", "roach", "ide", "rudd", "common_carp", "grass_carp", "silver_carp", "other"], "features": "Площадь 10,85 км², высота над уровнем моря 161 м."}', 'public', false, 'published'),
  ('ad936c04-5718-4c5d-a16d-f0d2da4e9fcf', private.editorial_id(), 'water_body', 'Тузколь', 'Солёное озеро (по данным OpenStreetMap) на высоте около 1950 м в Алматинской области.', 'SRID=4326;POINT(79.986931 43.002777)', null, '{"source": "osm", "osm": "r6334199", "features": "Солёное; высота около 1950 м."}', 'public', false, 'published'),
  ('0526b623-218e-4220-8087-93e771f788e5', private.editorial_id(), 'water_body', 'Тулькиколь', 'Озеро площадью около 86 га в 13 км к востоку от с. Мукур, в Костанайской области. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(64.979111 50.513438)', null, '{"source": "osm", "osm": "w1192694708", "features": "Площадь около 86 га (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('acd0c543-2343-4849-9c90-c5ee5be28654', private.editorial_id(), 'water_body', 'Тульколь', 'Озеро площадью около 1,7 км² в 5 км к юго-востоку от с. Сабит, в Северо-Казахстанской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(66.686878 54.459785)', null, '{"source": "osm", "osm": "w536824765", "features": "Площадь около 1,7 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('8b8cde91-4f22-49a8-8f7b-5bfebdc58828', private.editorial_id(), 'water_body', 'Тундик', 'Озеро площадью около 2,3 км² в Павлодарской области.', 'SRID=4326;POINT(77.434881 51.088752)', null, '{"source": "osm", "osm": "r21190520", "features": "Площадь около 2,3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b7d692d4-48fd-4770-a620-b7c212c0bfe2', private.editorial_id(), 'water_body', 'Тургусунское водосховище', 'Водохранилище площадью около 49 га в 15 км к северу от с. Осиновка, в Восточно-Казахстанской области.', 'SRID=4326;POINT(84.056353 49.959533)', null, '{"source": "osm", "osm": "r20122900", "features": "Площадь около 49 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('56816859-1fb2-435d-819e-0238e52d7e15', private.editorial_id(), 'water_body', 'Тущы кол', 'Озеро площадью около 15 км² в 6 км к западу от с. Аккулак, в Кызылординской области.', 'SRID=4326;POINT(61.263951 46.084198)', null, '{"source": "osm", "osm": "w39208979", "features": "Площадь около 15 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('bb493ec1-fd35-428f-b257-2c52627785c5', private.editorial_id(), 'water_body', 'Тызтыгын', 'Озеро площадью около 12 км² в 6 км к югу от с. Целинное, в Костанайской области. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(62.723942 53.378969)', null, '{"source": "osm", "osm": "w247062616", "features": "Площадь около 12 км² (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b44eca93-afd5-4078-9ac2-440586cc2330', private.editorial_id(), 'water_body', 'Угловое', 'Озеро площадью около 81 га в 7 км к северу от с. Луговое, в Костанайской области. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(63.162435 52.763399)', null, '{"source": "osm", "osm": "w411273677", "features": "Площадь около 81 га (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('58d2c7a0-6f77-4bfb-9810-e796ffe18657', private.editorial_id(), 'water_body', 'Узунколь', 'Озеро площадью около 11 км² в 3 км к северо-западу от с. Узунколь, в Акмолинской области.', 'SRID=4326;POINT(69.358766 51.520649)', null, '{"source": "osm", "osm": "w274957842", "features": "Площадь около 11 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('54590882-6d36-4fdb-b677-20a9c6423534', private.editorial_id(), 'water_body', 'Узынколь (Акмолинская обл.)', 'Озеро площадью около 6 км² в 2 км к северо-востоку от с. Узункольское, в Акмолинской области.', 'SRID=4326;POINT(69.945137 50.951778)', null, '{"source": "osm", "osm": "w320375717", "features": "Площадь около 6 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('f3ed4c0c-a72e-47ef-923f-72229534f345', private.editorial_id(), 'water_body', 'Узынколь (Костанайская обл.)', 'Озеро площадью около 2,6 км² у с. Первомайское, в Костанайской области.', 'SRID=4326;POINT(64.090859 52.986988)', null, '{"source": "osm", "osm": "w219561312", "features": "Площадь около 2,6 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('e154fca1-0013-4b4e-b01b-44e65d3b5674', private.editorial_id(), 'water_body', 'Уйдененское водохранилище', 'Небольшое водохранилище на реке Уйдене в Восточно-Казахстанской области, введено в 1966 году. Длина — около 3 км, площадь — 4,4 км², глубина — до 5 м.', 'SRID=4326;POINT(84.779653 47.371005)', null, '{"source": "osm", "osm": "r3120715", "features": "Длина около 3 км, ширина 1,5 км, площадь 4,4 км², глубина до 5 м."}', 'public', false, 'published'),
  ('0432a4b1-52a5-4816-a083-8182f1aef75d', private.editorial_id(), 'water_body', 'Улекты', 'Водохранилище площадью около 21 га у с. Теректы, в Западно-Казахстанской области.', 'SRID=4326;POINT(51.961354 51.213037)', null, '{"source": "osm", "osm": "w337350796", "features": "Площадь около 21 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('25d71805-6e31-4756-9ac0-4e28994af350', private.editorial_id(), 'water_body', 'Улкенкопа', 'Озеро площадью около 5,3 км² в 4 км к юго-западу от с. Богдановка, в Костанайской области.', 'SRID=4326;POINT(61.503325 51.796294)', null, '{"source": "osm", "osm": "w1458043922", "features": "Площадь около 5,3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('e91cc82a-7d50-4d76-8019-4090e68bfaf7', private.editorial_id(), 'water_body', 'Улькен-Караой', 'Солёное озеро у сёл Кулыколь и Талшик, в Акжарском районе. Площадь — около 306 км². В маловодные годы сильно пересыхает, в весеннее половодье верхний слой воды становится пресным. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(71.953649 53.993234)', null, '{"source": "osm", "osm": "w61462773", "features": "Площадь 305,5 км², длина 67,7 км, ширина 11,9 км, высота над уровнем моря 57 м. Вода солёная."}', 'public', false, 'published'),
  ('72152605-00d5-478b-96d1-7ec50564e11e', private.editorial_id(), 'water_body', 'Улькенжарма озеро', 'Озеро в 3 км к юго-западу от с. Борки, в Северо-Казахстанской области. Площадь — около 11 км²; наибольшая глубина — 1,98 м. Входит в перечень рыбохозяйственных водоёмов местного значения.', 'SRID=4326;POINT(69.711948 54.610045)', null, '{"source": "osm", "osm": "w1220982696", "features": "Площадь 10,71 км², длина 4,5 км, ширина 2,8 км, наибольшая глубина 1,98 м, высота над уровнем моря 126,3 м."}', 'public', false, 'published'),
  ('aea1e4f6-6e62-40df-9336-4e69b76b7934', private.editorial_id(), 'water_body', 'Унгирли', 'Озеро площадью около 47 га в 5 км к юго-западу от с. Абыла, в Кызылординской области.', 'SRID=4326;POINT(64.231643 45.346297)', null, '{"source": "osm", "osm": "w698581282", "features": "Площадь около 47 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('5a656bee-d6d7-4792-b916-42095cbd1e90', private.editorial_id(), 'water_body', 'Усек', 'Озеро площадью около 5 км² в 9 км к юго-востоку от с. Жидели, в области Жетісу.', 'SRID=4326;POINT(80.041885 43.931304)', null, '{"source": "osm", "osm": "w39372327", "features": "Площадь около 5 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b64a27e0-ebbb-453d-ba9f-57626a5d6f7a', private.editorial_id(), 'water_body', 'Усть-Каменогорское водохранилище', 'Водохранилище на Иртыше между плотинами Бухтарминской и Усть-Каменогорской ГЭС; на берегах — Серебрянск, Огнёвка, Сурово. В нём отмечено больше 20 видов рыб, среди них лещ, судак, сазан, налим, ёрш и елец.', 'SRID=4326;POINT(82.965822 49.709978)', null, '{"source": "osm", "osm": "r2087409", "species": ["bream", "zander", "common_carp", "burbot", "ruffe"], "methods": ["shore", "boat", "ice"], "features": "Узкое и глубокое: длина около 77 км, площадь около 37 км², глубина до 46 м (в среднем около 17 м)."}', 'public', false, 'published'),
  ('26e9283c-92bf-4e99-9cab-9d05f759d00d', private.editorial_id(), 'water_body', 'Утиное', 'Озеро площадью около 43 га в 7 км к западу от с. Николаевка, в Акмолинской области.', 'SRID=4326;POINT(69.505877 52.477074)', null, '{"source": "osm", "osm": "w150168784", "features": "Площадь около 43 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('06e0e162-af3f-4281-8bd7-8977fc7e8837', private.editorial_id(), 'water_body', 'Ушколь (Акмолинская обл.)', 'Озеро площадью около 2,3 км² в 11 км к юго-востоку от с. Узунколь, в Акмолинской области.', 'SRID=4326;POINT(69.511642 51.439471)', null, '{"source": "osm", "osm": "w322997958", "features": "Площадь около 2,3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('cde7fb2b-576c-4edd-b36c-5344228c783c', private.editorial_id(), 'water_body', 'Ушколь (ВКО)', 'Озеро площадью около 16 га в 8 км к востоку от с. Рахмановские Ключи, в Восточно-Казахстанской области, на высоте около 2100 м.', 'SRID=4326;POINT(86.617459 49.544295)', null, '{"source": "osm", "osm": "w842373163", "features": "Площадь около 16 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('a94b5c07-a34a-42c1-9dca-64acd17d11d0', private.editorial_id(), 'water_body', 'Ушконыр', 'Горное озеро на высоте около 2100 м, в 43 км к юго-западу от центра Алматы по прямой.', 'SRID=4326;POINT(76.490272 43.040950)', null, '{"source": "osm", "osm": "w182958493", "features": "Высота около 2100 м."}', 'public', false, 'published'),
  ('0a1c2c94-6e86-41f4-a8b4-f192afbc45bb', private.editorial_id(), 'water_body', 'Ушкулын', 'Озеро площадью около 58 га в 5 км к западу от с. Ушкулун, в Павлодарской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(75.639912 51.433191)', null, '{"source": "osm", "osm": "w403343907", "features": "Площадь около 58 га (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('952d2d98-b276-447f-b04b-e112f03b4e02', private.editorial_id(), 'water_body', 'Уштаган (Акмолинская обл.)', 'Озеро площадью около 81 га в 3 км к югу от с. Бирлик, в Акмолинской области.', 'SRID=4326;POINT(69.460390 51.606900)', null, '{"source": "osm", "osm": "w322720539", "features": "Площадь около 81 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('e7fc7c45-4592-46c6-a91b-add2b6cbfbe5', private.editorial_id(), 'water_body', 'Уштаган (обл. Абай)', 'Озеро площадью около 3,7 км² в 2 км к юго-востоку от с. Жазык, в области Абай.', 'SRID=4326;POINT(79.337206 50.090407)', null, '{"source": "osm", "osm": "w533951028", "features": "Площадь около 3,7 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('2c6e8af3-6172-4970-9b89-0bd2813bd9c7', private.editorial_id(), 'water_body', 'Уялы', 'Озеро площадью около 3 км² в 8 км к югу от с. Шарбакты, в Павлодарской области.', 'SRID=4326;POINT(78.262579 51.318219)', null, '{"source": "osm", "osm": "w344114708", "features": "Площадь около 3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b061965b-3de5-488d-a739-db1e06f1caa6', private.editorial_id(), 'water_body', 'Уялы озеро (с. Трудовое, СКО)', 'Озеро у с. Трудовое, в Северо-Казахстанской области. Площадь — около 2 км²; наибольшая глубина — 3,5 м. Входит в перечень рыбохозяйственных водоёмов местного значения.', 'SRID=4326;POINT(68.428251 54.580320)', null, '{"source": "osm", "osm": "w536681255", "features": "Площадь 2,02 км², длина 1,8 км, ширина 1,5 км, наибольшая глубина 3,5 м, высота над уровнем моря 134,7 м."}', 'public', false, 'published'),
  ('504c2212-ad81-4f06-a37f-63ba6cccb1c6', private.editorial_id(), 'water_body', 'Фёдоровское водохранилище', 'Водохранилище в черте Караганды — затопленный в 1960 году Фёдоровский угольный разрез. Пополняется паводком реки Сокур и водой канала «Иртыш — Караганда». На водохранилище есть спасательная станция и яхт-клуб.', 'SRID=4326;POINT(73.086382 49.754728)', null, '{"source": "osm", "osm": "r14975947", "features": "Длина 4,1 км, ширина 2,2 км, площадь 4,32 км², объём 83 млн м³."}', 'public', false, 'published'),
  ('dd0ecd04-d895-444a-9e36-9228a5ec0ed3', private.editorial_id(), 'water_body', 'Холостое', 'Озеро площадью около 1,8 км² в 9 км к юго-западу от с. Калмак, в Западно-Казахстанской области. По данным OpenStreetMap, вода солёная, а озеро временами пересыхает. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(49.218981 50.708081)', null, '{"source": "osm", "osm": "w405096999", "features": "Площадь около 1,8 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('525dedbf-f512-4b13-aeb1-4146310f1961', private.editorial_id(), 'water_body', 'Хомутина', 'Озеро площадью около 28 га в 6 км к северо-западу от с. Кенжеколь, в Павлодарской области.', 'SRID=4326;POINT(76.968180 52.229036)', null, '{"source": "osm", "osm": "w527888388", "features": "Площадь около 28 га (по данным OpenStreetMap). Вода пресная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('578a87f4-64c8-4ab6-bb6a-3ca303f557ac', private.editorial_id(), 'water_body', 'Центральное озера', 'Озеро площадью около 2 га в 5 км к юго-востоку от с. Токжайлау, в области Жетісу, на высоте около 1100 м.', 'SRID=4326;POINT(81.146002 45.791504)', null, '{"source": "osm", "osm": "w1232428643", "features": "Площадь около 2 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('cba3114a-de64-45b3-a5e8-77afd1842024', private.editorial_id(), 'water_body', 'Церковное озеро', 'Озеро площадью около 1 км² у с. Макарьевка, в Северо-Казахстанской области.', 'SRID=4326;POINT(66.350087 54.511633)', null, '{"source": "osm", "osm": "w251775879", "features": "Площадь около 1 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('a6a5d7bd-c05b-49c3-8867-ad01eaac1458', private.editorial_id(), 'water_body', 'Чапурино', 'Озеро площадью около 13 га в 5 км к северо-западу от с. Подстёпное, в Западно-Казахстанской области.', 'SRID=4326;POINT(51.428073 51.171712)', null, '{"source": "osm", "osm": "r10978218", "features": "Площадь около 13 га (по данным OpenStreetMap). Вода пресная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('e80b1c79-8bda-42b2-be07-314f97b880c7', private.editorial_id(), 'water_body', 'Чарское водохранилище', 'Водохранилище площадью около 6,3 км² в 6 км к востоку от с. Орумбай, в области Абай.', 'SRID=4326;POINT(81.813756 49.240453)', null, '{"source": "osm", "osm": "w22751250", "features": "Площадь около 6,3 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('d36956c3-b6fa-45be-b0e7-b5583a0e5ce9', private.editorial_id(), 'water_body', 'Чаша Армакай', 'Горное озеро на высоте около 2250 м, в 30 км к востоку от центра Алматы по прямой. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(77.311643 43.236725)', null, '{"source": "osm", "osm": "w1328188170", "features": "Высота около 2250 м."}', 'public', false, 'published'),
  ('bb5e3563-59a1-4009-a57d-c01287a49413', private.editorial_id(), 'water_body', 'Ченчарка', 'Озеро площадью около 66 га в 7 км к северо-востоку от с. Новочеркасское, в Акмолинской области.', 'SRID=4326;POINT(69.952853 51.464743)', null, '{"source": "osm", "osm": "w316177982", "features": "Площадь около 66 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('8a4a0cb2-2d03-43bb-bd82-5a2331d0b175', private.editorial_id(), 'water_body', 'Чёрненький Ярок', 'Старица площадью около 40 га в 6 км к юго-востоку от с. Жанабулак, в Западно-Казахстанской области.', 'SRID=4326;POINT(51.101426 50.269673)', null, '{"source": "osm", "osm": "w334279531", "features": "Площадь около 40 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b047ea04-84a2-43df-818d-564d51733eb3', private.editorial_id(), 'water_body', 'Чигири', 'Озеро площадью около 3 га в 2 км к западу от с. Кенжеколь, в Павлодарской области. По данным OpenStreetMap, его питают подземные ключи.', 'SRID=4326;POINT(76.997754 52.188600)', null, '{"source": "osm", "osm": "w1448196909", "features": "Площадь около 3 га; питают подземные ключи (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('c8bf0308-1baf-476b-8b7e-60b70bb60324', private.editorial_id(), 'water_body', 'Чистое озеро (Костанайская обл.)', 'Озеро площадью около 2 км² в 8 км к северо-востоку от с. Самир, в Костанайской области.', 'SRID=4326;POINT(63.679146 53.402917)', null, '{"source": "osm", "osm": "w235536224", "features": "Площадь около 2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('0a3e4139-ccd6-4928-8b78-2370d1661183', private.editorial_id(), 'water_body', 'Чистое озеро (обл. Абай)', 'Озеро площадью около 4,4 км² в 18 км к юго-востоку от с. Кокентау, в области Абай. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(79.759695 49.960811)', null, '{"source": "osm", "osm": "w533951029", "features": "Площадь около 4,4 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('cb79e998-3efa-4156-8fea-c941dd519ed3', private.editorial_id(), 'water_body', 'Чкаловское водохранилище', 'Небольшое водохранилище на Нуре в Карагандинской области; объём — около 6 млн м³.', 'SRID=4326;POINT(72.960685 49.928559)', null, '{"source": "osm", "osm": "w537459035", "features": "Объём около 6 млн м³."}', 'public', false, 'published'),
  ('70a1ef61-8e82-4f9c-afe8-3d19196e9e0e', private.editorial_id(), 'water_body', 'Шабынды', 'Озеро площадью около 38 км² в 11 км к юго-востоку от с. Шидерты, в Карагандинской области.', 'SRID=4326;POINT(73.688597 50.555675)', null, '{"source": "osm", "osm": "w1226237609", "features": "Площадь около 38 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('349000a5-0e09-40df-8226-2112aebb7d0b', private.editorial_id(), 'water_body', 'Шагала (Кызылординская обл.)', 'Озеро площадью около 65 га в Кызылординской области.', 'SRID=4326;POINT(64.059100 45.903348)', null, '{"source": "osm", "osm": "w698590421", "features": "Площадь около 65 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('ca8141bc-c14a-42c9-b7a3-6430d1dbf2b7', private.editorial_id(), 'water_body', 'Шагалакколь', 'Озеро площадью около 50 га в 12 км к юго-западу от с. Кайындыколь, в Костанайской области.', 'SRID=4326;POINT(62.584771 52.205222)', null, '{"source": "osm", "osm": "r5388167", "features": "Площадь около 50 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('f054438f-314e-47c8-81c5-8b1d125c16f9', private.editorial_id(), 'water_body', 'Шагырколь', 'Озеро площадью около 5,1 км² в 9 км к северо-востоку от с. Свободное, в Костанайской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(62.656995 51.683340)', null, '{"source": "osm", "osm": "w295998420", "features": "Площадь около 5,1 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('3adc122c-5c71-448f-9c55-51eff6ea311c', private.editorial_id(), 'water_body', 'Шайтанколь', 'Чёртово озеро — в 5 км к западу от Каркаралинска (Карагандинская область). Его окружают гранитные скалы, похожие на слоёный пирог, и сосновый лес; питание снеговое. Про озеро рассказывают много легенд: в 1905 году на берегу поставили крест и назвали его Святым, но крест пропал, и название вернулось.', 'SRID=4326;POINT(75.393510 49.396928)', null, '{"source": "osm", "osm": "w194260610", "features": "Окружено гранитными скалами и сосновым лесом; питание снеговое."}', 'public', false, 'published'),
  ('a8c2eccc-c936-4851-9a9d-9eb993d0cd7b', private.editorial_id(), 'water_body', 'Шакпак', 'Озеро площадью около 1,5 км² у с. Шакпак, в Костанайской области.', 'SRID=4326;POINT(65.602932 50.365313)', null, '{"source": "osm", "osm": "w220308623", "features": "Площадь около 1,5 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('8e42bd15-072c-46e4-8043-e9c37ac435cf', private.editorial_id(), 'water_body', 'Шалкар (ВКО)', 'Озеро площадью около 2,7 км² в 6 км к востоку от с. Алгабас, в Восточно-Казахстанской области.', 'SRID=4326;POINT(82.637952 49.442780)', null, '{"source": "osm", "osm": "w24949281", "features": "Площадь около 2,7 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('9aa17787-da7c-4a95-839f-c8b13eac179a', private.editorial_id(), 'water_body', 'Шалкар-Карашатау.', 'Солёное озеро в 9 км к западу от с. Кумкудук, в Актюбинской области. Площадь — около 18 км². Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(61.097590 50.468620)', null, '{"source": "osm", "osm": "w206225907", "features": "Площадь 18,5 км², длина 12,5 км, ширина 2,2 км, высота над уровнем моря 239 м. Вода солёная."}', 'public', false, 'published'),
  ('b41f7ef0-5221-4350-88ec-125f6568f9ed', private.editorial_id(), 'water_body', 'Шалкар (СКО)', 'Бессточное слабосолёное озеро из группы Кокшетауских озёр, в 7 км от с. Шалкар. Площадь — около 30 км²; наибольшая глубина — 11 м. Исконная рыба — окунь; вселены ряпушка, пелядь, карп, золотой и серебряный карась.', 'SRID=4326;POINT(68.399812 53.194250)', null, '{"source": "osm", "osm": "r947707", "species": ["perch", "vendace", "other", "common_carp", "crucian_carp"], "features": "Площадь 29,6 км², длина 9,49 км, ширина 2,95 км, наибольшая глубина 11 м (средняя 5,34 м), высота над уровнем моря 309,7 м."}', 'public', false, 'published'),
  ('a5c5a34f-eb6a-47a6-bbaf-21a2ffcaeb75', private.editorial_id(), 'water_body', 'Шалкарбай (сол.)', 'Озеро площадью около 21 га в 8 км к северо-западу от с. Жананегиз, в Карагандинской области.', 'SRID=4326;POINT(75.412927 49.509003)', null, '{"source": "osm", "osm": "w424760536", "features": "Площадь около 21 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('b5483fb9-72ff-48c6-a711-297ecdc80bba', private.editorial_id(), 'water_body', 'Шалкарколь', 'Водохранилище площадью около 2,8 км² у с. Шалкар, в Карагандинской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(74.899656 50.235739)', null, '{"source": "osm", "osm": "w398895822", "features": "Площадь около 2,8 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('94ee6a0b-ba7a-4329-97fe-31ce263bc157', private.editorial_id(), 'water_body', 'Шандыколь', 'Озеро площадью около 4,5 км² в 8 км к юго-западу от с. Полтавское, в Акмолинской области.', 'SRID=4326;POINT(69.667825 51.076784)', null, '{"source": "osm", "osm": "w322713931", "features": "Площадь около 4,5 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('db8babc8-0df3-44ef-8672-ef6e6113629c', private.editorial_id(), 'water_body', 'Шардаринское водохранилище', 'Крупное водохранилище на Сырдарье в Туркестанской области, на границе с Узбекистаном. На плотине — Шардаринская ГЭС, вода идёт и на орошение по Кызылкумскому каналу. Длина — около 80 км, ширина — до 25 км, площадь — 783 км². Из-за южного положения водохранилище не замерзает.', 'SRID=4326;POINT(68.181250 41.094155)', null, '{"source": "osm", "osm": "r2860201", "features": "Длина около 80 км, ширина до 25 км, площадь 783 км², объём 5,7 км³; зимой не замерзает."}', 'public', false, 'published'),
  ('3359ff8e-9560-4158-86af-5cc3b6a91342', private.editorial_id(), 'water_body', 'Шепты Куль', 'Озеро площадью около 73 га в 5 км к западу от с. Иртышское, в Карагандинской области.', 'SRID=4326;POINT(73.190493 50.337729)', null, '{"source": "osm", "osm": "w1226241727", "features": "Площадь около 73 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('da2a0fd5-fbdb-4859-8db8-5858903f297e', private.editorial_id(), 'water_body', 'Шерубайнуринское водохранилище', 'Водохранилище на реке Шерубайнура (1960 год), на северном берегу — пос. Топар с Карагандинской ГРЭС-2. Площадь — около 39 км²; наибольшая глубина — 24 м. Водятся ёрш, щука, язь, налим и окунь. Берега пологие, местами — лесная полоса. Ниже по течению — Жартасское водохранилище.', 'SRID=4326;POINT(72.768731 49.490713)', null, '{"source": "osm", "osm": "w23484247", "species": ["ruffe", "pike", "ide", "burbot", "perch"], "features": "Площадь 39 км², длина 13 км, ширина 4,2 км, наибольшая глубина 24 м, высота над уровнем моря 533,2 м."}', 'public', false, 'published'),
  ('cfcf1a2b-46f4-486b-ac07-3a15361410b6', private.editorial_id(), 'water_body', 'Шетекен', 'Озеро площадью около 3,3 км² в 2 км к востоку от с. Жангала, в Западно-Казахстанской области. По данным OpenStreetMap, вода солёная. Рыба в солёных озёрах есть не всегда — если рыбачили здесь, расскажите в отчёте, что ловится.', 'SRID=4326;POINT(50.329828 49.211209)', null, '{"source": "osm", "osm": "w287057555", "features": "Площадь около 3,3 км² (по данным OpenStreetMap). Вода солёная (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('87f5955b-1e37-460b-9a7b-c5c8a434abc6', private.editorial_id(), 'water_body', 'Шидертинское водохранилище', 'Водохранилище на реке Шидерты в 50 км к западу от Экибастуза (Павлодарская область), сооружено в 1969 году на канале имени Каныша Сатпаева; его также называют водохранилищем гидроузла № 1. На восточном берегу — посёлок Шидерты. Вода пресная. Водятся судак, щука, лещ, плотва, окунь.', 'SRID=4326;POINT(74.659489 51.725481)', null, '{"source": "osm", "osm": "r9627209", "species": ["zander", "pike", "bream", "roach", "perch"], "features": "Длина около 18 км, средняя ширина 0,5 км, площадь 10,9 км², средняя глубина 7,6 м."}', 'public', false, 'published'),
  ('5dae1f4e-d9f4-47dd-81bf-cd9e115fe24f', private.editorial_id(), 'water_body', 'Шийли', 'Озеро площадью около 16 км² в 12 км к северо-востоку от с. Юльевка, в Костанайской области. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(64.416701 52.174363)', null, '{"source": "osm", "osm": "r9346034", "features": "Площадь около 16 км² (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('e02f117c-5e17-49e8-8e86-48bb8f002825', private.editorial_id(), 'water_body', 'Шиликты', 'Озеро площадью около 1,2 км² в 8 км к западу от с. Бесбидаик, в Акмолинской области.', 'SRID=4326;POINT(69.229671 51.181458)', null, '{"source": "osm", "osm": "w326910113", "features": "Площадь около 1,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('87758c97-1ff7-469e-90cb-f15f61d96317', private.editorial_id(), 'water_body', 'Широкая Ляга', 'Озеро площадью около 1 км² в 7 км к востоку от с. Ауельбек, в Павлодарской области.', 'SRID=4326;POINT(76.612786 52.680116)', null, '{"source": "osm", "osm": "w124683068", "features": "Площадь около 1 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('4603936d-6828-48e0-9586-ac78923fa647', private.editorial_id(), 'water_body', 'Широкие озера', 'Озеро площадью около 7,9 км² в 5 км к северо-западу от с. Ивановка, в Северо-Казахстанской области.', 'SRID=4326;POINT(68.889321 54.694653)', null, '{"source": "osm", "osm": "w203286397", "features": "Площадь около 7,9 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('6154d84f-0e54-4114-ba7b-6668b3dc2c77', private.editorial_id(), 'water_body', 'Шобан', 'Озеро площадью около 3,1 км² у с. Шобан, в Костанайской области. По данным OpenStreetMap, временами пересыхает.', 'SRID=4326;POINT(63.982125 50.230248)', null, '{"source": "osm", "osm": "w1191613269", "features": "Площадь около 3,1 км² (по данным OpenStreetMap). Временами пересыхает (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('c3822788-90d1-42a8-8fd0-04f03fd2c585', private.editorial_id(), 'water_body', 'Шоиндыколь', 'Солоноватое озеро в 4 км к юго-востоку от с. Шойындыколь, в Акмолинской области. Площадь — около 19 км²; средняя глубина — 0,3–0,4 м.', 'SRID=4326;POINT(67.325151 50.451806)', null, '{"source": "osm", "osm": "w283874244", "features": "Площадь 18,84 км², длина 6,4 км, ширина 5 км, средняя глубина 0,3–0,4 м, высота над уровнем моря 325 м. Вода солоноватая."}', 'public', false, 'published'),
  ('62b4145e-ba43-4e86-956f-7fa4b9c56fbf', private.editorial_id(), 'water_body', 'Шокпартас', 'Озеро площадью около 2 га в 13 км к востоку от с. Карасу, в Карагандинской области.', 'SRID=4326;POINT(75.309593 49.345623)', null, '{"source": "osm", "osm": "w427967414", "features": "Площадь около 2 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('0450961f-cc1d-4c63-b3e9-a4c282f4a451', private.editorial_id(), 'water_body', 'Шомишколь', 'Озеро площадью около 4,2 км² в 2 км к юго-западу от с. Шомишколь, в Кызылординской области.', 'SRID=4326;POINT(61.657902 45.909560)', null, '{"source": "osm", "osm": "w39208963", "features": "Площадь около 4,2 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('63c73c11-aec9-4fc8-8481-fa615c71bf42', private.editorial_id(), 'water_body', 'Шоптыколь', 'Озеро площадью около 13 га в 4 км к югу от с. Новочеркасское, в Акмолинской области.', 'SRID=4326;POINT(69.881808 51.385513)', null, '{"source": "osm", "osm": "w323008583", "features": "Площадь около 13 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('7845d19d-eb14-47b6-9ee7-27825ff06085', private.editorial_id(), 'water_body', 'Шортанды', 'Озеро площадью около 9 га в 8 км к юго-востоку от г. Каркаралинск, в Карагандинской области.', 'SRID=4326;POINT(75.559025 49.373633)', null, '{"source": "osm", "osm": "w427768500", "features": "Площадь около 9 га (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('d4751eb1-6735-44cf-92e4-dc726917dbe1', private.editorial_id(), 'water_body', 'Шортанколь', 'Озеро площадью около 4,4 км² у с. Новорыбинка, в Акмолинской области.', 'SRID=4326;POINT(71.219882 51.849219)', null, '{"source": "osm", "osm": "w270539436", "features": "Площадь около 4,4 км² (по данным OpenStreetMap)."}', 'public', false, 'published'),
  ('3ba4ff71-9434-4eb5-9d35-4a74641aa42e', private.editorial_id(), 'water_body', 'Шотландия', 'Высокогорное озеро в Заилийском Алатау на высоте около 3450 м, в 28 км к югу от центра Алматы по прямой. На такой высоте озеро свободно ото льда только летом, а погода в горах меняется быстро: идите с прогнозом и скажите близким маршрут.', 'SRID=4326;POINT(76.921860 42.986492)', null, '{"source": "osm", "osm": "w1064801873", "features": "Высота около 3450 м."}', 'public', false, 'published'),
